CardSets.register({"id": "chairs", "name": "Chairs", "code": "CHAIR", "description": "351 cards celebrating the chair in all its forms — thrones and design icons at the top, and at the bottom, the most-sat-in objects on Earth.", "theme": {"primary": "#5a3d26", "secondary": "#c9963c", "artBackground": "#1f150e", "artFit": "cover"}, "pack": {"name": "Chairs Pack", "emblem": "🪑", "skin": "chairs", "slots": [{"count": 5, "label": "Common", "odds": {"common": 100}}, {"count": 2, "label": "Uncommon", "odds": {"uncommon": 100}}, {"count": 1, "label": "Wild card", "odds": {"common": 55, "uncommon": 30, "rare": 12, "epic": 3}}, {"count": 1, "label": "Rare or better (guaranteed)", "odds": {"rare": 81.8, "epic": 14, "legendary": 4, "chase": 0.2}}], "holo": {"common": 1, "uncommon": 1.5, "rare": 3, "epic": 5, "legendary": 7.5, "chase": 12.5}}, "cards": [{"name": "Lockheed Lounge", "rarity": "chase", "id": "lockheed-lounge", "subtitle": "Design Icon", "details": "Marc Newson's riveted aluminium chaise, bent like a jet-age daydream; auction examples have fetched millions of dollars.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv%20design%2C%20marc%20newson%2C%20lc2%20lockheed%20lounge%201985-86.JPG?width=1024"}, {"name": "Red and Blue Chair", "rarity": "chase", "id": "red-and-blue-chair", "subtitle": "Design Icon", "details": "Gerrit Rietveld's 1918 chair rebuilt as pure planes of primary colour — De Stijl you can sit on, though comfort was never the point.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rietveld_chair_1.JPG?width=1024"}, {"name": "Sedia Gestatoria", "rarity": "chase", "id": "sedia-gestatoria", "subtitle": "Throne", "details": "The popes' portable throne, carried on the shoulders of twelve footmen in red, so the pontiff could bless crowds without touching the ground.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Papst%20Pius%20XII.%2C%20Kr%C3%B6nung%2010.%20Jahrestag.jpg?width=1024"}, {"name": "The Coronation Chair", "rarity": "chase", "id": "the-coronation-chair", "subtitle": "Throne", "details": "Carved in oak around 1300 to cradle Scotland's Stone of Scone, it has seated nearly every English and British monarch at their coronation.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coronation%20Chair-0001.jpg?width=1024"}, {"name": "The Dragon Throne", "rarity": "chase", "id": "the-dragon-throne", "subtitle": "Throne", "details": "The emperors of China ruled from this dragon-carved seat in the Forbidden City's Hall of Supreme Harmony, the largest wooden throne in China.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/DragonThroneHallofSupremeHarmony.jpg?width=1024"}, {"name": "The Ejection Seat", "rarity": "chase", "id": "the-ejection-seat", "subtitle": "Work Chair", "details": "A Martin-Baker seat that has saved thousands of aircrew lives — a chair designed to leave the aircraft as fast as possible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Martin-Baker_Mk.7A.jpg?width=1024"}, {"name": "The Golden Stool", "rarity": "chase", "id": "the-golden-stool", "subtitle": "Throne", "details": "The soul of the Asante nation, in solid gold. It must never touch the ground or be sat in — not even by the king it belongs to.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20stool%2031%20January%201935.jpg?width=1024"}, {"name": "The Invisible Chair", "rarity": "chase", "id": "the-invisible-chair", "subtitle": "Weird Chair", "details": "There is no chair. A street performer sits on thin air, gripping a pole, while a hidden frame does the sitting for him. Mind the gap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/003%202014%2003%2018%20Strassenkuenstler.jpg?width=800"}, {"name": "The Iron Throne", "rarity": "chase", "id": "the-iron-throne", "subtitle": "Throne", "details": "Forged, in legend, from the swords of a thousand surrendered foes — the seat of Westeros' kings, as uncomfortable as ruling should be.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Iron%20Throne%20Moscow%20Metro%20%282019-05-11%29%2001.jpg?width=1024"}, {"name": "The Klismos Chair", "rarity": "chase", "id": "klismos-chair", "subtitle": "Historic Chair", "details": "Born in ancient Greece, its saber legs and curved back rail have been revived by designers for over 2,500 years.", "image": "https://bigfoto.name/photo/uploads/posts/2023-03/thumbs/1679511043_bigfoto-name-p-stul-klismos-47.jpg"}, {"name": "Ball Chair", "rarity": "legendary", "id": "ball-chair", "subtitle": "Design Icon", "details": "Eero Aarnio's 1963 globe on a pedestal: swivel inside and the world goes quiet — 'a room within a room'.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv%20design%2C%20eero%20aarnio%2C%20globe%20chair%201963-65%2001.JPG?width=1024"}, {"name": "Big Easy Chair", "rarity": "legendary", "id": "big-easy", "subtitle": "Design Icon", "details": "Ron Arad's voluptuous 1988 armchair in polished steel, hammered and welded at his One Off workshop in London.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ron%20arad%2C%20poltrona%20big%20easy%2C%201987.JPG?width=1024"}, {"name": "Captain Kirk's Chair", "rarity": "legendary", "id": "captain-kirks-chair", "subtitle": "Work Chair", "details": "The Enterprise command chair from Star Trek: a swivel throne with built-in controls, and the most famous captain's seat in fiction.", "image": "https://www.patrickkphillips.com/wp-content/uploads/2016/07/star-trek-command-chair-enterprise.jpg"}, {"name": "Cathedra of St. Peter", "rarity": "legendary", "id": "cathedra-of-st-peter", "subtitle": "Throne", "details": "Bernini encased a battered wooden chair said to be St Peter's own in a floating bronze throne, held aloft by four giant Doctors of the Church.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cathedra%20Petri%20-%20Saint%20Peter%27s%20Basilica.jpg?width=1024"}, {"name": "Charlemagne's Throne", "rarity": "legendary", "id": "charlemagnes-throne", "subtitle": "Throne", "details": "Four plain marble slabs on stone pillars, raised in Aachen around 790. Thirty-one German kings were crowned on its deliberate simplicity.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aachener%20Dom%20BW%202016-07-09%2013-53-18.jpg?width=1024"}, {"name": "Chinese Horseshoe-Back Armchair", "rarity": "legendary", "id": "chinese-horseshoe-back-armchair", "subtitle": "Historic Chair", "details": "Its sweeping horseshoe crest rail, bent from a single piece of wood in the Ming era, signals rank and welcome.", "image": "https://assets-cdn.vam.ac.uk/2017/09/18/15/45/57/957a42b5-8652-484f-9953-118b2f3e706b/amazing-ming-study-day_1920.jpg"}, {"name": "Eames Lounge Chair", "rarity": "legendary", "id": "eames-lounge-chair", "subtitle": "Design Icon", "details": "Charles and Ray Eames, 1956: moulded rosewood shells and black leather meant to feel like a well-worn baseball mitt.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eameslounch.jpg?width=1024"}, {"name": "Egg Chair", "rarity": "legendary", "id": "egg-chair", "subtitle": "Design Icon", "details": "Arne Jacobsen designed it in 1958 for Copenhagen's SAS Royal Hotel — a swivel cocoon you can turn away from the room in.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Egg_chair_-_Arne_Jacobsen_%281958%29.jpg?width=1024"}, {"name": "IKEA Poäng", "rarity": "legendary", "id": "poang-chair", "subtitle": "Everyday Chair", "details": "An icon in bent birch and fabric, sold in the tens of millions. It bounces slightly, on purpose, forever.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Woman_on_Po%C3%A4ng_chair.jpg?width=1024"}, {"name": "Ivory Throne of Ivan IV", "rarity": "legendary", "id": "ivory-throne-of-ivan-iv", "subtitle": "Throne", "details": "Ivan the Terrible's throne, faced with carved ivory and walrus bone telling biblical stories — even the seat came with illustrations.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ivans%20ivory%20throne.jpg?width=1024"}, {"name": "LC4 Chaise Longue", "rarity": "legendary", "id": "lc4-chaise-longue", "subtitle": "Design Icon", "details": "Le Corbusier, Perriand and Jeanneret's 1928 'relaxing machine': a steel frame that slides to any recline you like.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/LC4%2C_chaise_longue.png?width=1024"}, {"name": "Old Sparky", "rarity": "legendary", "id": "old-sparky", "subtitle": "Work Chair", "details": "Sing Sing prison's electric chair, used from 1891 to 1963. New York's executions moved upstate, and the grim nickname travelled with the chair.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Singchair.jpg?width=1024"}, {"name": "Panton Chair", "rarity": "legendary", "id": "panton-chair", "subtitle": "Design Icon", "details": "Verner Panton's 1960 S-curve was the first chair moulded in one piece of plastic — a single gesture you can sit on.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv%20design%2C%20verner%20panton%2C%20panton%20chair%2C%201960%2001.JPG?width=700"}, {"name": "Peacock Chair", "rarity": "legendary", "id": "peacock-chair", "subtitle": "Outdoor Chair", "details": "A throne-sized fan of woven rattan from the Philippines. Sitting in one instantly makes any portrait look like an album cover.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/The%20Raina%20Peacock%20Chair%20by%20Vito%20Selma.jpg?width=1024"}, {"name": "Proust Chair", "rarity": "legendary", "id": "proust-chair", "subtitle": "Design Icon", "details": "Alessandro Mendini's baroque armchair hand-painted in pointillist dots — a garden party frozen onto a museum throne.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Alessandro%20Mendini%20Poltrona%20di%20Proust%20Studio%20Alchimia%201979%20Mus%C3%A9e%20des%20arts%20d%C3%A9coratifs%20Paris.jpg?width=1024"}, {"name": "Roman Curule Chair", "rarity": "legendary", "id": "roman-curule-chair", "subtitle": "Historic Chair", "details": "An X-framed folding seat reserved for Rome's highest magistrates — the original power chair, designed to travel.", "image": "https://iuliotrylvfpzsfj.1tvv.live/pikapi/images/b56005f9-3233-4aa2-8416-2d6aa1bf0e07/2048"}, {"name": "The Chrysanthemum Throne", "rarity": "legendary", "id": "the-chrysanthemum-throne", "subtitle": "Throne", "details": "Japan's octagonal Takamikura throne in Kyoto, used only for enthronements — a canopied seat for the world's oldest hereditary monarchy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Imperial%20throne.jpg?width=1024"}, {"name": "The Koken Barber Chair", "rarity": "legendary", "id": "the-koken-barber-chair", "subtitle": "Work Chair", "details": "Ernest Koken's 1900 hydraulic barber chair let one chair recline, swivel and lift — the design every barbershop chair since has copied.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Footplate_detail_on_a_barber's_chair_at_Tocino_(53276206113).jpg?width=1024"}, {"name": "The Marble Throne", "rarity": "legendary", "id": "the-marble-throne", "subtitle": "Throne", "details": "Carved from yellow Yazd marble for Persia's Fath-Ali Shah, its legs are demons and fairies said to have carried the stone to Tehran themselves.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Marble%20Throne%202.JPG?width=1024"}, {"name": "The Peacock Throne", "rarity": "legendary", "id": "the-peacock-throne", "subtitle": "Throne", "details": "Shah Jahan's jewel-crusted Mughal throne, carried off to Persia in 1739 and dismantled — lost, but its name now means any grand throne.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sixteen%20views%20of%20monuments%20in%20Delhi%20Peacock%20Throne%20Red%20Fort%20Delhi%201850.png?width=1024"}, {"name": "The Porcelain Throne", "rarity": "legendary", "id": "the-porcelain-throne", "subtitle": "Weird Chair", "details": "Every home has a throne room. It flushes, it reigns over the plumbing, and it is the one seat nobody is allowed to reserve.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Flush%20toilet.jpg?width=1024"}, {"name": "The Silver Throne", "rarity": "legendary", "id": "the-silver-throne", "subtitle": "Throne", "details": "Sweden's throne of solid silver, made for Queen Christina's coronation in 1650 and still kept in Stockholm's Royal Palace for royal occasions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Throne%20of%20Sweden%201982.jpg?width=1024"}, {"name": "Throne of Tutankhamun", "rarity": "legendary", "id": "throne-of-tutankhamun", "subtitle": "Throne", "details": "Gilded wood and glass inlay from the boy king's tomb; its back panel shows Tutankhamun relaxing while his queen anoints him with perfume.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tutankhamun%20throne%202.jpg?width=1024"}, {"name": "Tulip Chair", "rarity": "legendary", "id": "tulip-chair", "subtitle": "Design Icon", "details": "Saarinen, 1956: one moulded pedestal instead of legs — he hated the 'slum of legs' under ordinary tables and chairs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eero_saarinen_per_knoll_international%2C_sedia_tulip_dalla_collezione_pedestal%2C_1955-56.jpg?width=1024"}, {"name": "UP Chair", "rarity": "legendary", "id": "up-chair", "subtitle": "Design Icon", "details": "Gaetano Pesce's 1969 UP5 shipped vacuum-flat, then inflated itself when unboxed; its ball ottoman is chained like a ball and chain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%22%2009%20-%20ITALY%20-%20TDM%20-%20Red%20armchair%20-%20Serie%20UP%20%28UP5%20and%20UP6%29%20Gaetano%20Pesce%20chairs%20and%20B%26B%20Italia%20at%20Triennale%20Design%20Museum.jpg?width=1024"}, {"name": "Womb Chair", "rarity": "legendary", "id": "womb-chair", "subtitle": "Design Icon", "details": "Eero Saarinen, 1948: Florence Knoll asked for a chair she could curl up in, and fibreglass gave her a womb with cushions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eero_Saarinen%2C_Womb_Chair%2C_Model_No._70%2C_Designed_1947-1948.jpg?width=1024"}, {"name": "Aeron Chair", "rarity": "epic", "id": "aeron-chair", "subtitle": "Work Chair", "details": "Herman Miller's 1994 mesh landmark ditched foam for a pellicle suspension seat. It became the dot-com era's definitive office throne.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aeron_chair_Brooklyn_Museum.jpg?width=1024"}, {"name": "Barcelona Chair", "rarity": "epic", "id": "barcelona-chair", "subtitle": "Design Icon", "details": "Mies van der Rohe, 1929, for Spain's king and queen at the Barcelona Pavilion: flat steel crosses dressed in leather.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv_design%2C_ludwig_mies_van_der_rohe_%26_co%2C_barcelona_chair.JPG?width=1024"}, {"name": "Bergère", "rarity": "epic", "id": "bergere", "subtitle": "Historic Chair", "details": "France's answer to comfort: a wide, deep, fully upholstered armchair built for lounging, from the early 1700s.", "image": "https://assets-vinterior-0.vinterior.co/uploads/listing_image/image/12746917/large-19th-century-french-carved-walnut-bergere-upholstered-armchair-sku83238722_0.jpg"}, {"name": "Bone Chair", "rarity": "epic", "id": "bone-chair", "subtitle": "Design Icon", "details": "Joris Laarman's 2006 chair was 'grown' by software mimicking bone growth, then cast in aluminium — evolution as furniture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Laarman%20Bone-Chair%2001.jpg?width=1024"}, {"name": "Broken Chair", "rarity": "epic", "id": "broken-chair", "subtitle": "Weird Chair", "details": "Geneva's 39-foot wooden chair stands on three and a half legs outside the UN, a monument against landmines. Sitting respectfully declined.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/At%20Geneva%202024%20064%20-%20Broken%20Chair.jpg?width=1024"}, {"name": "Bubble Chair", "rarity": "epic", "id": "bubble-chair", "subtitle": "Design Icon", "details": "Eero Aarnio hung a clear acrylic bubble from a chain in 1968, because the Ball Chair needed a window and a skyhook.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bubble%20Chair%20Eero%20Aarnio.jpg?width=1024"}, {"name": "Chippendale Chair", "rarity": "epic", "id": "chippendale-chair", "subtitle": "Historic Chair", "details": "Thomas Chippendale's 1754 pattern book spread its pierced splats and cabriole legs across Britain and America.", "image": "https://collectionapi.metmuseum.org/api/collection/v1/iiif/1859/25136/main-image"}, {"name": "Danish Throne Chair", "rarity": "epic", "id": "danish-throne-chair", "subtitle": "Throne", "details": "Denmark's coronation chair is narwhal tusk passed off as unicorn horn, guarded at Rosenborg by three life-size lions cast in solid silver.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coronation%20Chair%20Denmark%20%28King%29.jpg?width=1024"}, {"name": "Diamond Chair", "rarity": "epic", "id": "diamond-chair", "subtitle": "Design Icon", "details": "Harry Bertoia, 1952: welded steel rods bent into a sculptural lattice — Bertoia said it was made mainly of air.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Diamond_Chair_-_Harry_Bertoia%2C_MNAM.jpg?width=1024"}, {"name": "Ghost Chair", "rarity": "epic", "id": "ghost-chair", "subtitle": "Design Icon", "details": "Cini Boeri and Tomu Katayanagi bent one 12mm sheet of glass in 1987 — a chair that is barely there at all.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cini%20boeri%20e%20tomu%20katayanagi%2C%20poltrona%20ghost%2C%20in%20vetro%20curvato%2C%201987.jpg?width=1024"}, {"name": "Golden Throne of Mysore", "rarity": "epic", "id": "golden-throne-of-mysore", "subtitle": "Throne", "details": "A gold-plated seat assembled only for the Dasara festival, when the maharaja holds court — the rest of the year it stays locked away in pieces.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Srikanta%20Wadiyar%20of%20Mysore.jpg?width=1024"}, {"name": "Hanging Egg Chair", "rarity": "epic", "id": "hanging-egg-chair", "subtitle": "Outdoor Chair", "details": "A cocoon of rattan on a stand, first designed in 1959. Half chair, half hiding place — the garden's most requested seat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hanging%20Egg%20Chair%20.jpg?width=1024"}, {"name": "Hill House Chair", "rarity": "epic", "id": "hill-house-chair", "subtitle": "Design Icon", "details": "Charles Rennie Mackintosh, 1902: a ladder-back so tall and strict it was meant as art for the room, not daily sitting.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/National_Museum_of_Ethnology%2C_Osaka_-_Chair_%22Ladder-back_chair%22_-_Glasgow_in_United_Kingdom_-_Made_by_Charles_Rennie_Mackintosh_in_2006_%28originally_1903%29.jpg?width=1024"}, {"name": "Home Theater Chair", "rarity": "epic", "id": "home-theater-chair", "subtitle": "Everyday Chair", "details": "A recliner with cupholders, a motorised back and cinema ambitions, parked in front of a television.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dedicated_home_theater.jpg?width=1024"}, {"name": "How High the Moon", "rarity": "epic", "id": "how-high-the-moon", "subtitle": "Design Icon", "details": "Shiro Kuramata wove this 1986 armchair from steel mesh and named it after a jazz standard; it weighs almost nothing.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shiro%20kuramata%2C%20poltrona%20how%20high%20the%20moon%2C%201986-87.JPG?width=1024"}, {"name": "Knotted Chair", "rarity": "epic", "id": "knotted-chair", "subtitle": "Design Icon", "details": "Marcel Wanders knotted carbon and aramid cord like macramé in 1996, then set it hard with epoxy resin.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cappellini%20knotted%20chair.jpg?width=700"}, {"name": "Louis Ghost", "rarity": "epic", "id": "louis-ghost", "subtitle": "Design Icon", "details": "Philippe Starck's 2002 Kartell bestseller: a Louis XV armchair reborn as a single shot of clear polycarbonate.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Table%20%26%20Chairs%20by%20Philippe%20Starck.jpg?width=1024"}, {"name": "Massage Chair", "rarity": "epic", "id": "massage-chair", "subtitle": "Everyday Chair", "details": "A chair with kneading rollers and strong opinions about your shoulders. The mall demo that moved in.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Human_Touch_iJoy-2580_Robotic_Massage_Chair_Black_%286798775063%29.jpg?width=1024"}, {"name": "Miss Blanche", "rarity": "epic", "id": "miss-blanche", "subtitle": "Design Icon", "details": "Shiro Kuramata cast silk roses inside clear acrylic in 1988 — flowers that never wilt, in a chair you can see through.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shiro%20kuramata%2C%20poltrona%20miss%20blanche%2C%201989.JPG?width=1024"}, {"name": "Movie Theatre Recliner Seat", "rarity": "epic", "id": "movie-theatre-recliner", "subtitle": "Everyday Chair", "details": "A cinema seat that leans back, raises your feet, and makes leaving before the credits feel physically difficult.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Luxury_Movie_Theater_Seats.jpg?width=1024"}, {"name": "Paimio Chair", "rarity": "epic", "id": "paimio-chair", "subtitle": "Design Icon", "details": "Alvar Aalto, 1932, for a tuberculosis sanatorium: its bent birch scroll was angled to help patients breathe easier.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv_design%2C_alvar_aalto%2C_armchair_41%2C_1930.JPG?width=1024"}, {"name": "Ski Lift Chair", "rarity": "epic", "id": "ski-lift-chair", "subtitle": "Outdoor Chair", "details": "A bench that flies. It carries you up the mountain in the open air, then gets a second life as a porch swing when the lifts retire.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chairlift%20at%20Arthur%27s%20Seat%20Victoria%201961.jpg?width=1024"}, {"name": "St Augustine's Chair", "rarity": "epic", "id": "st-augustines-chair", "subtitle": "Throne", "details": "Canterbury's Purbeck marble chair, used to enthrone archbishops since the 1200s and named for St Augustine, the first man to hold the job.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Canterburycathedralthrone.jpg?width=1024"}, {"name": "Swan Chair", "rarity": "epic", "id": "swan-chair", "subtitle": "Design Icon", "details": "Jacobsen, 1958, also for the SAS Royal Hotel: no straight lines anywhere, just foam over fibreglass curves.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv_design%2C_arne_jacobsen%2C_swan_chair%2C_1958.JPG?width=1024"}, {"name": "The Director's Chair", "rarity": "epic", "id": "the-directors-chair", "subtitle": "Work Chair", "details": "A folding canvas-and-wood chair borrowed from campaign furniture. On a film set, the tall back carries the director's name like a title card.", "image": "https://images.stockcake.com/public/5/f/c/5fc89f18-e317-46a1-a823-3bcc82099c3c_large/director-s-chair-set-stockcake.jpg"}, {"name": "The Electric Chair", "rarity": "epic", "id": "the-electric-chair", "subtitle": "Work Chair", "details": "Introduced in New York in 1890 as a supposedly humane technology, it became America's most feared piece of furniture. Retired in most states.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Florida_electric-chair.jpg?width=1024"}, {"name": "The Lion Throne", "rarity": "epic", "id": "the-lion-throne", "subtitle": "Throne", "details": "Chief of Mandalay Palace's eight thrones, named for the lions at its base. The original burned in 1945; today's is a faithful reconstruction.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lion%20throne%2C%20Mandalay%20Palace.jpg?width=1024"}, {"name": "The Naderi Throne", "rarity": "epic", "id": "the-naderi-throne", "subtitle": "Throne", "details": "A golden, enamelled throne studded with jewels, made in Qajar Persia and named for Nader Shah — now among Tehran's crown-jewel treasures.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Naderi%20throne.jpg?width=1024"}, {"name": "The Phoenix Throne", "rarity": "epic", "id": "the-phoenix-throne", "subtitle": "Throne", "details": "The crimson seat in Seoul's Geunjeongjeon Hall, named for its phoenix carvings and backed by a painted screen of five mountain peaks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Seoul%20Throne%20in%20Geunjeongjeon%2003.jpg?width=1024"}, {"name": "The Round Chair", "rarity": "epic", "id": "the-round-chair", "subtitle": "Design Icon", "details": "Wegner, 1949: the chair Kennedy and Nixon sat in for their 1960 TV debate, afterwards known simply as The Chair.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chair_JH503.png?width=1024"}, {"name": "The Sun Throne", "rarity": "epic", "id": "the-sun-throne", "subtitle": "Throne", "details": "Golestan's jewel-covered throne, named for the sunburst carved on its back. Built for Fath-Ali Shah of Persia and later used at Pahlavi weddings.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/-Golestan%2C%20The%20Peacock%20Throne%2C%20Teheran%2C%20Iran-%20%28Takht-I%20Taous%29%20MET%20DP202914.jpg?width=1024"}, {"name": "The Tennis Umpire Chair", "rarity": "epic", "id": "the-tennis-umpire-chair", "subtitle": "Work Chair", "details": "The umpire sits over two metres up so the whole court, and every disputed line, stays in view. Reached by ladder, ruled from above.", "image": "https://ad-in.me/images/umpire-chair.jpg"}, {"name": "Throne of Dagobert", "rarity": "epic", "id": "throne-of-dagobert", "subtitle": "Throne", "details": "A bronze folding throne of the Merovingian kings, part camp stool and part crown jewel, kept for centuries at the abbey of Saint-Denis.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cluny%20-%20Mero%20-%20Tr%C3%B4ne%20de%20Dagobert.jpg?width=1024"}, {"name": "Throne of Minos", "rarity": "epic", "id": "throne-of-minos", "subtitle": "Throne", "details": "A gypsum seat built into the wall at Knossos some 3,500 years ago — the oldest throne in Europe, still sitting in its own throne room.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Knossos%20throne.jpg?width=1024"}, {"name": "Throne of Napoleon", "rarity": "epic", "id": "throne-of-napoleon", "subtitle": "Throne", "details": "Napoleon rebuilt Fontainebleau's throne room around a gilded imperial seat under a crowned canopy — a Bourbon room, brand-new emperor.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/La%20salle%20du%20Tr%C3%B4ne%20%28Ch%C3%A2teau%20de%20Fontainebleau%29.jpg?width=1024"}, {"name": "Wiggle Side Chair", "rarity": "epic", "id": "wiggle-chair", "subtitle": "Design Icon", "details": "Frank Gehry's 1972 chair is corrugated cardboard, layered and bent until waste packaging became sculpture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Frank%20Gehry%20-%20Wiggle%20Side%20Chair%20-%20Museum%20Boijmans%20Van%20Beuningen.jpg?width=1024"}, {"name": "Wingback Chair", "rarity": "epic", "id": "wingback-chair", "subtitle": "Historic Chair", "details": "Tall wings shielded sitters from draughts and fireside heat in 1600s England; the fireside throne ever since.", "image": "https://images.metmuseum.org/CRDImages/es/original/DP-14129-043.jpg"}, {"name": "Wishbone Chair", "rarity": "epic", "id": "wishbone-chair", "subtitle": "Design Icon", "details": "Hans Wegner, 1949: a steam-bent top rail and hand-woven paper-cord seat — over 100 steps, still made in Denmark.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hans_J_Wegner_Wishbone_Chair.jpg?width=1024"}, {"name": "Zig Zag Chair", "rarity": "epic", "id": "zig-zag-chair", "subtitle": "Design Icon", "details": "Rietveld, 1934: four flat wooden planes joined in one confident Z, looking like it should fold up and never does.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gerrit_Thomas_Rietveld_Zig-Zag_1932.jpg?width=1024"}, {"name": "Acapulco Chair", "rarity": "rare", "id": "acapulco-chair", "subtitle": "Outdoor Chair", "details": "Woven cords radiate like sun rays on a steel frame, born in 1950s Acapulco. A beach resort icon you can see straight through.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Acapulco%20chair%20%28street%29.jpg?width=800"}, {"name": "Ashanti Stool", "rarity": "rare", "id": "ashanti-stool", "subtitle": "Historic Chair", "details": "Carved from a single block of wood in Ghana, its curved seat is said to hold its owner's soul.", "image": "https://okanly.com/wp-content/uploads/2025/02/Ashanti-stool-Brooklyn_Museum_22.1695-1024x681.jpg"}, {"name": "Brno Chair", "rarity": "rare", "id": "brno-chair", "subtitle": "Design Icon", "details": "Mies van der Rohe, 1930, for the Tugendhat Villa in Brno: a flat steel bar cantilever, elegant and very heavy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tugenhat_brno_chairs.png?width=1024"}, {"name": "Butterfly Chair", "rarity": "rare", "id": "butterfly-chair", "subtitle": "Design Icon", "details": "The 1938 BKF chair by Bonet, Kurchan and Ferrari-Hardoy: a sling of leather hung on a folding steel frame.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/BKF_Chair.jpg?width=1024"}, {"name": "Cesca Chair", "rarity": "rare", "id": "cesca-chair", "subtitle": "Design Icon", "details": "Breuer, 1928: cantilevered tube steel meets a cane seat — named decades later for his daughter Francesca.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Breuer_chair_2008.jpg?width=1024"}, {"name": "Chair No. 14", "rarity": "rare", "id": "chair-no-14", "subtitle": "Design Icon", "details": "Thonet, 1859: six pieces of steam-bent wood, ten screws, two nuts — the café chair that sold in the tens of millions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Thonet_Chair_No._14.JPG?width=1024"}, {"name": "Chair_One", "rarity": "rare", "id": "chair-one", "subtitle": "Design Icon", "details": "Konstantin Grcic's 2004 Magis chair is a die-cast aluminium lattice — geometry homework you can sit on, indoors or out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Konstantin%20grcic%20per%20magis%20spa.%2C%20sedia%20chair%20one%2C%202004.jpg?width=1024"}, {"name": "Chesterfield Armchair", "rarity": "rare", "id": "chesterfield-armchair", "subtitle": "Everyday Chair", "details": "Deep-buttoned leather, rolled arms and a low back built for libraries, clubs and serious sitting.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chesterfield_club_chair.jpg?width=1024"}, {"name": "Chieftain Chair", "rarity": "rare", "id": "chieftain-chair", "subtitle": "Design Icon", "details": "Finn Juhl, 1949: a teak frame with horn-like details inspired by weapons and tools, shown at Copenhagen's guild exhibition.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Finn_Juhl_-_Chieftain_chair.jpg?width=1024"}, {"name": "Choir Stall", "rarity": "rare", "id": "choir-stall", "subtitle": "Everyday Chair", "details": "Carved wooden seating in the chancel where the choir sits, often with hinged seats that flip up between hymns.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chichester_Cathedral_Choir%2C_West_Sussex%2C_UK_-_Diliff.jpg?width=1024"}, {"name": "Church Pew", "rarity": "rare", "id": "church-pew", "subtitle": "Everyday Chair", "details": "A long wooden bench built to seat a whole congregation — and to keep everyone awake through the longest sermon.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Troms%C3%B8_Cathedral_%28domkirke%29_Norway_interior._Pews_%28kirkebenker%29%2C_pillars_%28b%C3%A6res%C3%B8yler%29%2C_doors%2C_sunlight%2C_etc_Wooden_Gothic_Revival_style_church_1861_Chr._H._Grosch_2019-04-04_DSC02260.jpg?width=1024"}, {"name": "Cone Chair", "rarity": "rare", "id": "cone-chair", "subtitle": "Design Icon", "details": "Verner Panton's 1958 swivel chair balanced on the point of an inverted cone — geometry homework you can sit on.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Verner%20Panton%20-%20Cone%20Chair.jpg?width=1024"}, {"name": "Djinn Chair", "rarity": "rare", "id": "djinn-chair", "subtitle": "Design Icon", "details": "Olivier Mourgue's low-slung 1965 Djinn seating became immortal as the red chairs of 2001: A Space Odyssey.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stanley%20Kubrick%20The%20Exhibition%20-%20LACMA%20-%202001%20A%20Space%20Odyssey%20-%20Olivier%20Mourge%20Djinn%20chair%20and%20sofa%20%288998536189%29.jpg?width=1024"}, {"name": "Eames LCW", "rarity": "rare", "id": "eames-lcw", "subtitle": "Design Icon", "details": "1945: the Eameses finally bent plywood in two directions at once; Time magazine called it the design of the century.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/First_Generation_LCW_Plywood_Lounge_Chair_attributed_to_Charles_Eames_-_DPLA_-_389a3892a7537afebd0de7fa37b2f371_%28page_2%29.jpg?width=1024"}, {"name": "Eames Molded Plastic Chair", "rarity": "rare", "id": "eames-molded-plastic-chair", "subtitle": "Design Icon", "details": "1950: among the first mass-produced plastic shell chairs, born from a MoMA low-cost furniture competition.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eames_chair-IMG_4624.jpg?width=1024"}, {"name": "Elkhorn Chair", "rarity": "rare", "id": "elkhorn-chair", "subtitle": "Weird Chair", "details": "Frontiersman Seth Kinman built chairs from elk antlers and gave them to presidents. Lincoln received this one; the elk was not consulted.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kinman%20Elkhorn%20chair.jpg?width=1024"}, {"name": "Favela Chair", "rarity": "rare", "id": "favela-chair", "subtitle": "Design Icon", "details": "The Campana brothers glued hundreds of scrap-wood slats in 2003, echoing the improvised building of São Paulo's favelas.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Favela%20by%20Fernando%20and%20Humberto%20Campana%20%28Edra%29%2C%20Salone%20Internazionale%20del%20Mobile%202009%20%283477175203%29.jpg?width=1024"}, {"name": "Feltri Chair", "rarity": "rare", "id": "feltri-chair", "subtitle": "Design Icon", "details": "Gaetano Pesce's 1987 throne for Cassina is thick wool felt stiffened with resin; the tall back wraps around you.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gaetano%20pesce%20per%20cassina%2C%20poltrona%20feltri%2C%201987.jpg?width=1024"}, {"name": "Imperial Hall Throne", "rarity": "rare", "id": "imperial-hall-throne", "subtitle": "Throne", "details": "The sultan's canopied seat in Topkapi Palace's Imperial Hall, raised above the harem's musicians — part sofa, part throne, all authority.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Topkapi%20Palace%20Imperial%20Hall%20Harem%20.jpg%2004.jpg?width=1024"}, {"name": "Isokon Long Chair", "rarity": "rare", "id": "isokon-long-chair", "subtitle": "Design Icon", "details": "Breuer's 1935 long chair for London's Isokon company: one flowing ribbon of bent plywood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Marcel_Breuer._Long_Chair%2C_ca._1935-1936.jpg?width=1024"}, {"name": "Japanese Zaisu", "rarity": "rare", "id": "japanese-zaisu", "subtitle": "Historic Chair", "details": "A legless chair for tatami floors, keeping floor-sitting posture while adding a back to rest against.", "image": "https://ae01.alicdn.com/kf/S735bb770ab564a0ab9ba283b7a8a6868c/Zaisu-Legless-Chair-for-Sitting-on-The-Floor-Unique-Janpanese-Tatami-Armchair-Seat-with-Cushion-Living.jpg_640x640.jpg"}, {"name": "Lifeguard Chair", "rarity": "rare", "id": "lifeguard-chair", "subtitle": "Outdoor Chair", "details": "A tall chair with a view over the whole beach, reached by a ladder. From up there, its sitter is part referee, part lighthouse.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/CL%20Lifeguard%20chair%20%287652127382%29%20%282%29.jpg?width=1024"}, {"name": "Louis XVI Fauteuil", "rarity": "rare", "id": "louis-xvi-fauteuil", "subtitle": "Historic Chair", "details": "A neoclassical French armchair: straight fluted legs, an oval back, and carving borrowed from ancient Rome.", "image": "https://collectionapi.metmuseum.org/api/collection/v1/iiif/189387/460323/main-image"}, {"name": "Lutyens Garden Bench", "rarity": "rare", "id": "lutyens-garden-bench", "subtitle": "Outdoor Chair", "details": "Edwin Lutyens' early-1900s garden bench, with rolled arms and a sweeping back. The most imitated silhouette in garden history.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Copped%20Hall%20Thakeham%20Lutyens%20bench%20Epping%2C%20Essex%2C%20England.jpg?width=1024"}, {"name": "Medical Examination Chair", "rarity": "rare", "id": "medical-examination-chair", "subtitle": "Everyday Chair", "details": "Adjustable, wipe-clean, and always slightly colder than expected. It has heard every symptom description there is.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eye_examination_equipment_set_up_in_a_modern_clinic_during_daylight_hours.jpg?width=1024"}, {"name": "MR10 Chair", "rarity": "rare", "id": "mr10-chair", "subtitle": "Design Icon", "details": "Mies van der Rohe, 1927: a continuous loop of tubular steel that bounces gently — the cantilever perfected.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ludwig_mies_van_der_rohe%2C_sedia_MR_10%2C_1927.JPG?width=1024"}, {"name": "Muskoka Chair", "rarity": "rare", "id": "muskoka-chair", "subtitle": "Outdoor Chair", "details": "Canada's twin of the Adirondack, from Ontario's Muskoka lakes. Same chair, fiercely different name — never confuse the two at a cottage.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Muskoka%20Chairs%20-%20Port%20Carling%20-%20Canada%20%285159311050%29.jpg?width=1024"}, {"name": "Nguyen Dynasty Throne", "rarity": "rare", "id": "nguyen-dynasty-throne", "subtitle": "Throne", "details": "The gilded, red-lacquered throne in Hue's Thai Hoa Palace — the last imperial seat of Vietnam, still in the hall built for it in 1805.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Throne%20%287351159086%29.jpg?width=1024"}, {"name": "Papasan Chair", "rarity": "rare", "id": "papasan-chair", "subtitle": "Everyday Chair", "details": "A giant rattan bowl tilted for lounging, with a cushion like a nest. Impossible to sit in formally.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Papasan_chair_and_footstool.jpg?width=1024"}, {"name": "Pastil Chair", "rarity": "rare", "id": "pastil-chair", "subtitle": "Design Icon", "details": "Eero Aarnio's 1967 fibreglass Pastil rocks and swivels on its own round base — a lozenge you lounge in.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pastilli%20Chair%20by%20Eero%20Aarnio.JPG?width=1024"}, {"name": "Porch Swing", "rarity": "rare", "id": "porch-swing", "subtitle": "Outdoor Chair", "details": "A bench on chains, hung from the porch ceiling. Hebron, Nebraska supersized one to seat a crowd — its slow creak sets the tempo for summer.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/World%27s%20Largest%20Porch%20Swing%20-%20Hebron%2C%20NE.jpg?width=1024"}, {"name": "Queen Anne Chair", "rarity": "rare", "id": "queen-anne-chair", "subtitle": "Historic Chair", "details": "Early 1700s elegance: a vase-shaped splat and cabriole legs, named for Queen Anne though it flowered after her reign.", "image": "https://collectionapi.metmuseum.org/api/collection/v1/iiif/1582/1513137/main-image"}, {"name": "Racing Bucket Seat", "rarity": "rare", "id": "racing-bucket-seat", "subtitle": "Work Chair", "details": "A deep shell that wraps the driver against cornering forces, with slots for a multi-point harness. Comfort is not the design brief.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Porsche_996_GT3_cockpit_(6293935112).jpg?width=1024"}, {"name": "Ribbon Chair", "rarity": "rare", "id": "ribbon-chair", "subtitle": "Design Icon", "details": "Pierre Paulin's 1966 Artifort lounge is a single ribbon of foam and fabric looped over a tubular steel frame.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Artifort%20Ribbon%20by%20Pierre%20Paulin.jpg?width=1024"}, {"name": "S Chair", "rarity": "rare", "id": "s-chair", "subtitle": "Design Icon", "details": "Tom Dixon's swooping S-curve, hand-woven in marsh straw over a steel frame — an early icon of new British design.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/S-Chair%20by%20Tom%20Dixon.jpg?width=1024"}, {"name": "Series 7 Chair", "rarity": "rare", "id": "series-7-chair", "subtitle": "Design Icon", "details": "Arne Jacobsen, 1955: layers of moulded veneer in one hourglass silhouette — millions sold, endlessly copied.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jacobsen%2C_7an.jpg?width=1024"}, {"name": "Shaker Chair", "rarity": "rare", "id": "shaker-chair", "subtitle": "Historic Chair", "details": "Shaker ladder-backs were hung on wall pegs when not in use — light, honest, and built by the thousand in America.", "image": "https://emuseum.colonialwilliamsburg.org/internal/media/dispatcher/200050/full"}, {"name": "Slipper Chair", "rarity": "rare", "id": "slipper-chair", "subtitle": "Everyday Chair", "details": "An armless, low upholstered chair made for bedrooms and dressing rooms. Small footprint, grand manners.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Slipper_Chair_MET_192988.jpg?width=1024"}, {"name": "Spun Chair", "rarity": "rare", "id": "spun-chair", "subtitle": "Design Icon", "details": "Thomas Heatherwick's 2010 Magis seat is a spinning top scaled up: lean back and it rolls with you, never over.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spun%20magis%20red%20wiki.jpg?width=1024"}, {"name": "Standard Chair", "rarity": "rare", "id": "standard-chair", "subtitle": "Design Icon", "details": "Jean Prouvé, 1934: skinny front legs, hugely strong back legs — because that's where a sitter's weight really lands.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chair_by_Jean_Prouv%C3%A9_for_Vitra.jpeg?width=1024"}, {"name": "Stool 60", "rarity": "rare", "id": "stool-60", "subtitle": "Design Icon", "details": "Aalto, 1933: the L-leg, bent from a single piece of birch, stackable and still in production nearly a century on.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Alvar_Aalto._Stool_60.jpg?width=1024"}, {"name": "Superonda", "rarity": "rare", "id": "superonda", "subtitle": "Design Icon", "details": "Archizoom's 1966 wave for Poltronova is a sofa that unzips into two pieces — surf the living room, split the wave.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Archizoom%20per%20poltronova%2C%20sofa%20superonda%2C%20vinile%20su%20gommapiuma%2C%201967.jpg?width=1024"}, {"name": "Swivel Rocker", "rarity": "rare", "id": "swivel-rocker", "subtitle": "Everyday Chair", "details": "Swivels, rocks and reclines: the full trifecta, in blue plush. The throne of grandparents' living rooms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/La-Z-Boy_chair_-_03.jpg?width=1024"}, {"name": "The Barber's Chair", "rarity": "rare", "id": "the-barbers-chair", "subtitle": "Work Chair", "details": "It reclines, swivels, pumps up and down, and comes with a headrest — because a good shave is precision work performed on a relaxed customer.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/MOHAI_-_J._N._Hooper's_Barber_Shop_-_A.jpg?width=1024"}, {"name": "The Big Chair", "rarity": "rare", "id": "the-big-chair", "subtitle": "Weird Chair", "details": "Thomasville, North Carolina — 'Chair City' — built this 30-foot chair in 1950 to advertise its furniture factories. It has its own traffic island.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/The%20Big%20Chair%202016%20%28cropped%29.jpg?width=1024"}, {"name": "The Dentist's Chair", "rarity": "rare", "id": "the-dentists-chair", "subtitle": "Work Chair", "details": "Engineered to tilt a patient nearly flat while keeping every tool in reach. Feared by many, remembered by all, sat in by almost everyone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/20140207_GCC_Dental_Clinic_@_Moss_(16466051851).jpg?width=1024"}, {"name": "The Drafting Chair", "rarity": "rare", "id": "the-drafting-chair", "subtitle": "Work Chair", "details": "A task chair stretched for tall desks: extra stem, a foot ring, and a view over the drawing board that made it the architect's standard seat.", "image": "https://images.squarespace-cdn.com/content/v1/53044cf7e4b0685242fd446e/1424689042996-RK5T9A4XFOPCLTJYGIUY/Vintage+Drafting+Stool.jpg.jpg?format=500w"}, {"name": "The Ducking Stool", "rarity": "rare", "id": "the-ducking-stool", "subtitle": "Weird Chair", "details": "A chair on the end of a long beam, built to dunk scolds and suspected witches in the river. Medieval seating, waterfront location.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/The%20Ducking%20Stool%20at%20Leominster%20-%20geograph.org.uk%20-%2015898.jpg?width=1024"}, {"name": "The Golden Toilet", "rarity": "rare", "id": "the-golden-toilet", "subtitle": "Weird Chair", "details": "Maurizio Cattelan's 'America' (2016) is a working toilet cast in solid 18-karat gold. Stolen from Blenheim Palace in 2019; never recovered.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/America%20%28Cattelan%29%20side%20view.jpg?width=1024"}, {"name": "The Hawaiian Throne", "rarity": "rare", "id": "the-hawaiian-throne", "subtitle": "Throne", "details": "The twin thrones of Honolulu's Iolani Palace, the only royal palace in the United States, built for King Kalakaua and Queen Kapiolani.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Iolani%20Palace%20Throne%20Room%20%2820189862396%29.jpg?width=1024"}, {"name": "The Judge's Chair", "rarity": "rare", "id": "the-judges-chair", "subtitle": "Work Chair", "details": "The elevated bench chair puts the judge above the courtroom on purpose: authority you can see, in dark wood and high-backed leather.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pioneer_Courthouse_interior_02.jpg?width=1024"}, {"name": "The Patriarch's Throne", "rarity": "rare", "id": "the-patriarchs-throne", "subtitle": "Throne", "details": "The Ecumenical Patriarch's throne in Istanbul's Cathedral of St George, seat of the first among equals of the Orthodox Christian world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Patriarch%20of%20Constantinople%20throne.jpg?width=1024"}, {"name": "The Pilot's Seat", "rarity": "rare", "id": "the-pilots-seat", "subtitle": "Work Chair", "details": "Built to survive enormous crash loads while keeping hundreds of controls in reach — and adjustable in almost every direction but out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Iran_Air_Boeing_747-200_cockpit_Sharifi.jpg?width=1024"}, {"name": "The Salon Chair", "rarity": "rare", "id": "the-salon-chair", "subtitle": "Work Chair", "details": "A hydraulic styling chair that spins for the mirror reveal. The pump pedal under every haircut is a century-old barber-chair inheritance.", "image": "https://static.livebooks.com/e855ff02c55e45f2ad75fba8e9f3e8f3/i/ff29acc869c44114876cbca8ad6a211a/1/4SoifmQpDrHbZJ6VybMjS/1_0_144_1hair_salon_chair.jpg"}, {"name": "The Ship Captain's Chair", "rarity": "rare", "id": "the-ship-captains-chair", "subtitle": "Work Chair", "details": "On a bridge, the captain's high chair sits centre with the whole ship in view — raised, winged, and unmistakably the seat of command.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2017-08-28_HS-Reise_Brücke_der_HEINRICH_SCHEPERS_(2221).jpg?width=1024"}, {"name": "The Shoeshine Chair", "rarity": "rare", "id": "the-shoeshine-chair", "subtitle": "Work Chair", "details": "An elevated throne for the customer and a footrest at working height — shoeshine stands turned a street service into a small ceremony.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Servicio_en_Villagrán,_Tamaulipas.jpg?width=1024"}, {"name": "The Sovereign's Throne", "rarity": "rare", "id": "the-sovereigns-throne", "subtitle": "Throne", "details": "The gilded throne in London's House of Lords, designed by Pugin, from which the monarch opens Parliament while the peers sit below in red.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Thrones%20in%20the%20House%20of%20Lords%20c1902.jpg?width=1024"}, {"name": "The Tattoo Chair", "rarity": "rare", "id": "the-tattoo-chair", "subtitle": "Work Chair", "details": "Part recliner, part workbench: it splits, tilts and flattens so the artist can reach any patch of skin while the client stays still.", "image": "https://www.trailertrashtattoo.net/wp-content/uploads/2020/11/Best-Tattoo-Artist-Chair-Client-Chair-Table-Bed.jpg"}, {"name": "The Vintage Dental Chair", "rarity": "rare", "id": "belmont-dental-chair", "subtitle": "Work Chair", "details": "Dental surgeries of the 1940s paired articulated lamps with hand-adjusted reclining chairs — dentistry before the lie-flat era.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dental_Surgery_of_1940s_and_1950s.jpg?width=1024"}, {"name": "The Wheelchair", "rarity": "rare", "id": "the-wheelchair", "subtitle": "Work Chair", "details": "A chair that is also a vehicle: self-propelled wheels were patented in the 1860s, and the folding tubular-steel design arrived in the 1930s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rolstoel_(1).jpg?width=1024"}, {"name": "Throne of Haakon VII", "rarity": "rare", "id": "throne-of-haakon-vii", "subtitle": "Throne", "details": "Haakon VII delivers the throne speech in 1950, seated on Norway's royal throne — a king, a chair, and a speech his government wrote for him.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/56255%20Haakon%20VII%20trontalen%201950.jpg?width=1024"}, {"name": "Throne of Jahangir", "rarity": "rare", "id": "throne-of-jahangir", "subtitle": "Throne", "details": "The Mughal emperor Jahangir's throne is a single slab of black stone made in 1602 — less a chair, more a royal claim carved in rock.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agra%20Fort%20-%20Jahangir%27s%20Throne.JPG?width=1024"}, {"name": "Thrones of Canada", "rarity": "rare", "id": "thrones-of-canada", "subtitle": "Throne", "details": "Ottawa's Senate chamber keeps thrones for the monarch and consort of Canada — grand red seats that wait patiently for the occasional royal visit.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Canadian-Senate-thrones.jpg?width=1024"}, {"name": "Tipu Sultan's Throne", "rarity": "rare", "id": "tipu-sultans-throne", "subtitle": "Throne", "details": "The Tiger of Mysore's gold octagonal throne stood under a jewelled tiger's head; after his fall in 1799 the throne was broken up for prize money.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tipu%20Sultan%20seated%20on%20his%20throne.jpg?width=1024"}, {"name": "Tom Vac", "rarity": "rare", "id": "tom-vac", "subtitle": "Design Icon", "details": "Ron Arad's 1997 shell for Vitra ripples like a wave and stacks in towers; first shown as a 100-chair sculpture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv%20design%2C%20ron%20arad%2C%20tom%20vac%20chair%2C%201997.JPG?width=1024"}, {"name": "Tube Chair", "rarity": "rare", "id": "tube-chair", "subtitle": "Design Icon", "details": "Joe Colombo's 1969 kit of four PVC tubes clips together any way you like — chair, lounger, or abstract plumbing.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tube%20chair%202.jpg?width=1024"}, {"name": "Warsaw Throne Chair", "rarity": "rare", "id": "warsaw-throne-chair", "subtitle": "Throne", "details": "The red-and-gold throne chair of Stanisław August, Poland's last king, in Warsaw's Royal Castle — it survived the castle's wartime destruction.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Warsaw%20Throne%20chair%20of%20Stanislaus%20Augustus.jpg?width=1024"}, {"name": "Wassily Chair", "rarity": "rare", "id": "wassily-chair", "subtitle": "Design Icon", "details": "Marcel Breuer, 1925: bent steel tubing borrowed from bicycle handlebars, named later for painter Wassily Kandinsky.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bauhaus_3_Chair.jpg?width=1024"}, {"name": "Adirondack Chair", "rarity": "uncommon", "id": "adirondack-chair", "subtitle": "Outdoor Chair", "details": "Designed in the Adirondack Mountains in 1903: wide armrests, a slanted back, and a permanent invitation to sit down and stay a while.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Typical%20Adirondack%20chair%20in%20eastern%20Ohio.jpg?width=1024"}, {"name": "Airport Beam Seating", "rarity": "uncommon", "id": "airport-beam-seating", "subtitle": "Everyday Chair", "details": "Seats bolted in a row to one metal beam, engineered so no traveller can ever quite lie down across them.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/BJ_%E5%8C%97%E4%BA%AC%E9%A6%96%E9%83%BD%E5%9C%8B%E9%9A%9B%E6%A9%9F%E5%A0%B4_Beijing_Capital_International_Airport_BCIA_interior_waiting_room_seats_Aug-2010.JPG?width=1024"}, {"name": "Ant Chair", "rarity": "uncommon", "id": "ant-chair", "subtitle": "Design Icon", "details": "Jacobsen, 1952: three legs and a seat shell pressed from one sheet of veneer, designed for a factory canteen.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ant_Chair_Arne_Jacobsen_%281952%29.jpg?width=1024"}, {"name": "Auditorium Seat", "rarity": "uncommon", "id": "auditorium-seat", "subtitle": "Everyday Chair", "details": "A tip-up seat in neat rows, built so hundreds of people can sit down, stand up, and applaud in unison.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2023-05-27_Savoy_Theatre_Interior.jpg?width=1024"}, {"name": "Banquet Chair", "rarity": "uncommon", "id": "banquet-chair", "subtitle": "Everyday Chair", "details": "A stackable padded chair wheeled out for weddings and awards nights, often wearing a sash for the occasion.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/DZ6_0468_Spacious_elegantly_lit_banquet_hall_set_up_with_rows_of_white-covered_chairs_facing_a_stage_ready_for_a_large_conference_or_formal_event.jpg?width=1024"}, {"name": "Belt Swing Seat", "rarity": "uncommon", "id": "belt-swing-seat", "subtitle": "Outdoor Chair", "details": "A flexible belt of rubber on two chains — the playground swing that fits every sitter and pumps higher than any rigid seat dares.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Swing%20seat.jpg?width=1024"}, {"name": "Bertoia Asymmetric Chaise", "rarity": "uncommon", "id": "bertoia-asymmetric-chaise", "subtitle": "Design Icon", "details": "Harry Bertoia, 1952: the wire grid of the Diamond collection twisted into a wave — half chaise, half sculpture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Assymetrical_chair_designed_by_Harry_Bertoia.jpg?width=1024"}, {"name": "Bleachers", "rarity": "uncommon", "id": "bleachers", "subtitle": "Everyday Chair", "details": "Long tiered benches with no backs at all, where school spirit is measured by how long you can sit comfortably.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Growden_Memorial_Park_Fairbanks_Alaska_Bleachers_and_Box_Seats.jpg?width=1024"}, {"name": "Butterfly Camp Chair", "rarity": "uncommon", "id": "butterfly-camp-chair", "subtitle": "Outdoor Chair", "details": "A sling seat hung in an X-frame, born as campaign furniture and adopted by campsites everywhere. Folds flat, leans back, refuses formality.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Biob%C3%BCffel-hardoy-butterfly-chair-by-manufakturplus.jpg?width=1024"}, {"name": "Cab Chair", "rarity": "uncommon", "id": "cab-chair", "subtitle": "Design Icon", "details": "Mario Bellini's 1977 Cab for Cassina is a leather skin zipped over a steel skeleton — the leather is the structure's clothing.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sedia%20cab%20anteprima.jpg?width=1024"}, {"name": "Camaleonda", "rarity": "uncommon", "id": "camaleonda", "subtitle": "Design Icon", "details": "Mario Bellini's 1970 modular sofa snaps together with rings and cables; its name mashes chameleon and onda, wave.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Camaleonda-modular-sofa%2010068.jpg?width=1024"}, {"name": "Cast Iron Garden Bench", "rarity": "uncommon", "id": "cast-iron-garden-bench", "subtitle": "Outdoor Chair", "details": "Heavy enough to stay exactly where history put it. Victorian parks were furnished with these, and many are still on duty.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cast%20iron%20bench.jpg?width=800"}, {"name": "Chair of Reniseneb", "rarity": "uncommon", "id": "chair-of-reniseneb", "subtitle": "Throne", "details": "A painted wooden chair from ancient Thebes, about 3,400 years old, its woven seat intact — one of the oldest recognisable chairs in the world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chair%20of%20Reniseneb%20MET%20DT536.jpg?width=1024"}, {"name": "Chaise Longue", "rarity": "uncommon", "id": "chaise-longue", "subtitle": "Historic Chair", "details": "French for 'long chair': part chair, part daybed, and an open invitation to put your feet up since the 1700s.", "image": "https://styylish.com/wp-content/uploads/2025/08/Image-11-800x800.jpeg"}, {"name": "Chinese Yoke-Back Chair", "rarity": "uncommon", "id": "chinese-yoke-back-chair", "subtitle": "Historic Chair", "details": "Its top rail flares like an official's hat — a Ming-dynasty silhouette of quiet authority.", "image": "https://assets-vinterior-3.vinterior.co/uploads/listing_image/image/19701058/large_antique-chinese-armchairs-pair-official-hat-yoke-back-lacquered-red-19th-century-carved-swastika-motifs-ming-qing-orienta-l-hall-chairs-country-house-sku64283940_0.jpg"}, {"name": "Cinema Seat", "rarity": "uncommon", "id": "cinema-seat", "subtitle": "Everyday Chair", "details": "Padded, tip-up, and upholstered in a pattern chosen to hide a decade of popcorn butter. It mostly succeeds.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/HK_%E8%8D%83%E7%81%A3_Tsuen_Wan_%E8%8D%83%E7%81%A3%E5%A4%A7%E6%9C%83%E5%A0%82_Tsuen_Wan_Town_Hall_theatre_interior_%E8%A7%80%E7%9C%BE%E5%B8%AD_red_chairs_November_2021_SS2_01.jpg?width=1024"}, {"name": "Conference Chair", "rarity": "uncommon", "id": "conference-chair", "subtitle": "Everyday Chair", "details": "A padded meeting-room chair on castors, equally suited to presentations, brainstorms, and very long agendas.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chairs_in_a_meeting_room_%28Unsplash%29.jpg?width=1024"}, {"name": "Conoid Chair", "rarity": "uncommon", "id": "conoid-chair", "subtitle": "Design Icon", "details": "George Nakashima: a hand-sculpted wooden seat on a sled base, with a comb of fine spindles for a back.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Conoid_Chair_by_George_Nakashima%2C_1988.jpg?width=1024"}, {"name": "Corner Chair", "rarity": "uncommon", "id": "corner-chair", "subtitle": "Historic Chair", "details": "Built to tuck into a corner, its round back wraps two sides — handy for writing, reading, or sitting astride.", "image": "https://emuseum.georgiamuseum.org/internal/media/dispatcher/9505/full"}, {"name": "Costes Chair", "rarity": "uncommon", "id": "costes-chair", "subtitle": "Design Icon", "details": "Philippe Starck designed this three-legged café chair in 1982 for Paris's Café Costes, so waiters could slip past.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Philippe%20starck%2C%20sedia%20costes%2C%201981.JPG?width=1024"}, {"name": "Craftsman Chair", "rarity": "uncommon", "id": "craftsman-chair", "subtitle": "Historic Chair", "details": "American Craftsman chairs wear their joinery proudly: quartersawn oak, mortise and tenon, nothing hidden.", "image": "https://a.1stdibscdn.com/l-j-g-stickley-antique-mission-oak-arts-crafts-armchair-newly-restored-for-sale-picture-3/f_27453/f_421118421730379481893/DSC_4689_master.JPG"}, {"name": "Dunk Tank Seat", "rarity": "uncommon", "id": "dunk-tank-seat", "subtitle": "Weird Chair", "details": "One small seat over a tank of cold water, one target, three balls. The seat's only job is betrayal, and it has never once failed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dunk%20tank.jpg?width=1024"}, {"name": "Eames Aluminum Group Chair", "rarity": "uncommon", "id": "eames-aluminum-group-chair", "subtitle": "Design Icon", "details": "1958: fabric slung taut between two aluminium rails — office seating that began as outdoor furniture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eames_Aluminum_Group_chairs_in_the_Federal_Chancellery_building_in_Berlin.jpg?width=1024"}, {"name": "Eames DCW", "rarity": "uncommon", "id": "eames-dcw", "subtitle": "Design Icon", "details": "The LCW's dining-height sibling, 1945: same bent-plywood magic, tuned for sitting up at a table.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Charles_e_ray_eames_per_herman_miller_inc.%2C_sedia_dcw%2C_1945-46.jpg?width=1024"}, {"name": "Egyptian Folding Stool", "rarity": "uncommon", "id": "egyptian-folding-stool", "subtitle": "Historic Chair", "details": "Folding X-frame stools served pharaohs over 4,000 years ago; Tutankhamun was buried with his.", "image": "https://i.pinimg.com/474x/ef/db/ef/efdbefd96fd28e2c4b45d5e7de2b438c.jpg"}, {"name": "Embryo Chair", "rarity": "uncommon", "id": "embryo-chair", "subtitle": "Design Icon", "details": "Marc Newson's 1988 biomorphic chaise in wetsuit neoprene — a comma of foam and aluminium from his Tokyo years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Embryo%20Chair.jpg?width=1024"}, {"name": "Executive Office Chair", "rarity": "uncommon", "id": "executive-office-chair", "subtitle": "Work Chair", "details": "Tall-backed, deep-cushioned and usually leather: the executive chair signals rank as much as it supports it. The corner office's soft throne.", "image": "https://i.pinimg.com/originals/fb/a1/1e/fba11e901b3acc2d74378adbef3ebef1.jpg"}, {"name": "Fjord Chair", "rarity": "uncommon", "id": "fjord-chair", "subtitle": "Design Icon", "details": "Patricia Urquiola split this 2002 Moroso shell like a fjord cutting into rock; the relax version swivels and reclines.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fjord%20Chair%20%282002%29.jpg?width=1024"}, {"name": "Giant Deckchair", "rarity": "uncommon", "id": "giant-deckchair", "subtitle": "Weird Chair", "details": "A deckchair scaled for a giant's day at the seaside. Britain keeps several; climbing in requires a ladder, a friend, and low standards of dignity.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bournemouth%2C%20a%20giant%20deckchair%20-%20geograph.org.uk%20-%202863329.jpg?width=1024"}, {"name": "Grasshopper Chair", "rarity": "uncommon", "id": "grasshopper-chair", "subtitle": "Design Icon", "details": "Saarinen, 1943-46: laminated wood legs sweeping back like a grasshopper about to leap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eero_Saarinen%2C_%22Grasshopper%22_Highback_Armchair%2C_Designed_ca._1947.jpg?width=1024"}, {"name": "Gustavian Chair", "rarity": "uncommon", "id": "gustavian-chair", "subtitle": "Historic Chair", "details": "Sweden's Gustavian style washed French neoclassicism in pale paint and northern light.", "image": "https://sav-images.auctionet.com/online/1603/371727-matgrupp-gustaviansk-stil/2500371727_3.jpg"}, {"name": "Hammock", "rarity": "uncommon", "id": "hammock", "subtitle": "Outdoor Chair", "details": "A bed of cloth strung between two trees — technically seating, in practice a full-day commitment. Two trees, zero plans.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hammocks%20and%20palm%20trees.jpg?width=1024"}, {"name": "Hand Chair", "rarity": "uncommon", "id": "hand-chair", "subtitle": "Weird Chair", "details": "Pedro Friedeberg's Hand Chair (1962) seats you in an open palm. The fingers are the backrest; the thumb minds its own business.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Silla%20-mano%2C%20Pedro%20Friedeberg.jpg?width=1024"}, {"name": "Heart Cone Chair", "rarity": "uncommon", "id": "heart-cone-chair", "subtitle": "Design Icon", "details": "Panton's 1959 follow-up to the Cone: two ears of upholstery folded into a heart you can sit in.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Verner%20Panton%20-%20Heart%20Cone%20chairs.jpg?width=1024"}, {"name": "Hepplewhite Chair", "rarity": "uncommon", "id": "hepplewhite-chair", "subtitle": "Historic Chair", "details": "George Hepplewhite's shield, heart and wheel backs made lightness fashionable in late 1700s Britain.", "image": "https://assets-vinterior-1.vinterior.co/uploads/listing_image/image/12156893/large_set-12-english-hepplewhite-revival-dining-chairs-20th-century-sku86619000_0.jpg"}, {"name": "Kneeling Chair", "rarity": "uncommon", "id": "kneeling-chair", "subtitle": "Everyday Chair", "details": "No back, a tilted seat and a pad for your knees. Posture improves; shins file a complaint.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kneeling_chair.jpg?width=1024"}, {"name": "Lecture Hall Seat", "rarity": "uncommon", "id": "lecture-hall-seat", "subtitle": "Everyday Chair", "details": "A fixed seat with a tiny fold-down desk, raked so everyone can see the board and nobody can comfortably nap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/NTNU_Trondheim%2C_lecture_hall_R1_during_COVID-19_pandemic.jpg?width=1024"}, {"name": "Library Chair", "rarity": "uncommon", "id": "library-chair", "subtitle": "Everyday Chair", "details": "A sturdy reading-room chair, usually wooden, in a place where the loudest sound allowed is turning a page.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kansas_Room_reading_chairs_%283653511797%29.jpg?width=1024"}, {"name": "Lift Chair", "rarity": "uncommon", "id": "lift-chair", "subtitle": "Everyday Chair", "details": "A recliner with a motor that gently stands you up. The chair does the standing for you.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lift_Chairs.jpg?width=1024"}, {"name": "Living Tower", "rarity": "uncommon", "id": "living-tower", "subtitle": "Design Icon", "details": "Verner Panton's 1969 seating sculpture packs niches for sitting, lying and lounging at four levels into one foam tower.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Living%20Tower.jpg?width=1024"}, {"name": "Ludovisi Throne", "rarity": "uncommon", "id": "ludovisi-throne", "subtitle": "Throne", "details": "A marble block carved around 460 BC showing Aphrodite rising from the sea. Whether it was ever a throne is still argued — it looks the part.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ludovisi%20throne%20Altemps%20Inv8570%20n4.jpg?width=1024"}, {"name": "Ming Chair", "rarity": "uncommon", "id": "ming-chair", "subtitle": "Historic Chair", "details": "Ming dynasty chairs pair sculpted joinery with open space — furniture as calligraphy, built without nails.", "image": "http://mail.buffaloah.com/a/virtual/china/shang_mus/jpegs/ming5.jpg"}, {"name": "Morris Chair", "rarity": "uncommon", "id": "morris-chair", "subtitle": "Historic Chair", "details": "Designed in William Morris's circle in the 1860s, its adjustable reclining back put craft ahead of factory furniture.", "image": "https://www.dousson.com/upload/thumbnails/2026/02/02/21/44/SIEGES-FAUTEUILS-Centre-Eure-et-Loir-Fauteuil-Morris02622324148656670.jpeg"}, {"name": "MR20 Armchair", "rarity": "uncommon", "id": "mr20-armchair", "subtitle": "Design Icon", "details": "Mies van der Rohe, 1927: the MR10 cantilever grows wicker armrests — springy tubular steel dressed for lounging.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ludwig_mies_van_der_rohe%2C_sedia_con_braccioli_MR_20%2C_1927-30.JPG?width=1024"}, {"name": "Méridienne", "rarity": "uncommon", "id": "meridienne", "subtitle": "Historic Chair", "details": "An asymmetrical French daybed with one high, sloping headrest — built for elegant midday reclining.", "image": "https://i55.servimg.com/u/f55/18/66/92/19/capt5232.png"}, {"name": "Nursing Chair", "rarity": "uncommon", "id": "nursing-chair", "subtitle": "Everyday Chair", "details": "Low, armless and made for feeding at 3 a.m. — the rocking chair that raised generations before gliders.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Nursing_student_wearing_a_starched_white_uniform%2C_seated_in_a_rocking_chair%2C_reading_LCCN99472219.jpg?width=1024"}, {"name": "Office Task Chair", "rarity": "uncommon", "id": "office-task-chair", "subtitle": "Work Chair", "details": "Adjustable height, lumbar support, five castors: the task chair is the negotiated settlement between a spine and an eight-hour day.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Prototype_ergonomic_office_chair,_V&A_London.jpg?width=1024"}, {"name": "Ottoman", "rarity": "uncommon", "id": "ottoman", "subtitle": "Everyday Chair", "details": "An armchair's loyal sidekick: footrest, spare seat and emergency coffee table in one upholstered block.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ottoman_in_a_living_room.jpg?width=800"}, {"name": "Outdoor Chaise Longue", "rarity": "uncommon", "id": "outdoor-chaise-longue", "subtitle": "Outdoor Chair", "details": "French for 'long chair' — a seat stretched out so your legs get furniture too. Garden luxury since the 16th century.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lounge%20chairs%20in%20hotel%20garden%20at%20sunset.jpg?width=1024"}, {"name": "Pacha Chair", "rarity": "uncommon", "id": "pacha-chair", "subtitle": "Design Icon", "details": "Pierre Paulin's 1975 cloud of a lounge chair sits deliberately low; revived by GUBI, it still hugs the floor.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pacha%20cu%20M%C3%A2ner%20armchair%2C%20by%20Pierre%20Paulin%20for%20GUBI%2C%201975%2C%20at%20sale%20at%20The%20Edit%20shop%20%28Strada%20Icoanei%20no.%2020%29%2C%20Bucharest%2C%20Romania.jpg?width=1024"}, {"name": "Papa Bear Chair", "rarity": "uncommon", "id": "papa-bear-chair", "subtitle": "Design Icon", "details": "Wegner, 1951: a fully upholstered armchair whose wooden 'paws' rest on top of the armrests, ready to hug.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hans_J._Wegner%27s_Papa_Bear_Chair.jpg?width=1024"}, {"name": "PK20 Lounge Chair", "rarity": "uncommon", "id": "pk20-chair", "subtitle": "Design Icon", "details": "Poul Kjærholm, 1968: a ribbon of leather sprung over a bowed steel frame — near-nothing, perfectly judged.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/PK20_lounge_chair_Poul_Kj%C3%A6rholm.jpg?width=1024"}, {"name": "Poolside Lounger", "rarity": "uncommon", "id": "poolside-lounger", "subtitle": "Outdoor Chair", "details": "Waterproof slats, wheels at one end, and a back that adjusts from reading to full nap. The pool deck's front row.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Drone%20pool%20and%20deck%20chairs%20%28Unsplash%29.jpg?width=1024"}, {"name": "Powered Wheelchair", "rarity": "uncommon", "id": "powered-wheelchair", "subtitle": "Work Chair", "details": "Electric wheelchairs went mainstream in the 1950s, trading push rims for a joystick and a motor — independence at walking pace and beyond.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pride_Jazzy_Select_power_chair_001.JPG?width=1024"}, {"name": "Prairie Chair", "rarity": "uncommon", "id": "prairie-chair", "subtitle": "Historic Chair", "details": "Frank Lloyd Wright designed chairs as architecture in miniature — tall backs that made dining rooms feel grand.", "image": "https://i.pinimg.com/474x/bb/70/00/bb7000eb2d4ba69637fd86a9b24771d3.jpg"}, {"name": "Pratone", "rarity": "uncommon", "id": "pratone", "subtitle": "Design Icon", "details": "Gruppo Strum's 1971 Gufram 'big meadow' is a field of giant polyurethane grass blades you lie down in. Indoors.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%22%2011%20-%20ITALY%20-%20Pratone.JPG?width=1024"}, {"name": "Rattan Chair", "rarity": "uncommon", "id": "rattan-chair", "subtitle": "Everyday Chair", "details": "Woven cane over bent rattan: light, springy, and legally required in every sunroom and beach cafe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rattan_chair.jpg?width=1024"}, {"name": "Recliner", "rarity": "uncommon", "id": "recliner", "subtitle": "Everyday Chair", "details": "Pull the lever, the footrest rises, and all plans for the evening are officially cancelled.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Black_Recliner.jpg?width=1024"}, {"name": "Risom Lounge Chair", "rarity": "uncommon", "id": "risom-lounge-chair", "subtitle": "Design Icon", "details": "Jens Risom, 1941: among the first Knoll chairs, woven with cotton webbing because wartime shortages ruled out leather.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jens_Risom._Lounge_Chair%2C_Model_654W._1941..jpg?width=1024"}, {"name": "Récamier", "rarity": "uncommon", "id": "recamier", "subtitle": "Historic Chair", "details": "Named for Madame Récamier's famous portrait pose: raised scrolled ends, no back, maximum drama.", "image": "https://intelligentcollector.com/wp-content/uploads/2017/11/couch-2.jpg"}, {"name": "Savonarola Chair", "rarity": "uncommon", "id": "savonarola-chair", "subtitle": "Historic Chair", "details": "An Italian Renaissance X-chair of interlaced slats that folds flat — Dante and Savonarola gave it its names.", "image": "https://www.museohorne.it/wordpress/wp-content/uploads/2019/02/Collezione_04_arredi_08_sediasavonarola.jpg"}, {"name": "Sella Curulis", "rarity": "uncommon", "id": "sella-curulis", "subtitle": "Throne", "details": "Rome's ivory folding stool, reserved for the highest magistrates. Holding office was literally holding the curule chair — backrest not included.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sella%20Curulis%20-%20Curule%20Seat%20around%201810.jpg?width=1024"}, {"name": "Shell Chair", "rarity": "uncommon", "id": "shell-chair", "subtitle": "Design Icon", "details": "Wegner's CH07, 1963: a smiling, wing-like plywood shell on three legs — briefly made, revived decades later.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shell_chair_%28Hans_J._Wegner%29.jpg?width=1024"}, {"name": "Sheraton Chair", "rarity": "uncommon", "id": "sheraton-chair", "subtitle": "Historic Chair", "details": "Thomas Sheraton favoured square tapered legs and rectangular backs — the crisp tailoring of Regency seating.", "image": "https://www.antiquesboutique.com/upload/images/shopprod/182540/antique-pair-sheraton-revival-side-chairs-ca-1900_182540_pic3_size1.jpg"}, {"name": "Sitamun's Throne", "rarity": "uncommon", "id": "sitamuns-throne", "subtitle": "Throne", "details": "A gilded wooden throne made for Princess Sitamun of Egypt around 1370 BC, its back carved with scenes of the princess receiving gifts of gold.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sitamun%20throne%202.jpg?width=1024"}, {"name": "Slice Chair", "rarity": "uncommon", "id": "slice-chair", "subtitle": "Design Icon", "details": "Mathias Bengtsson built this 1999 chair from dozens of individually cut slices, layered into a flowing wooden wave.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Slice%20Chair%20by%20Mathias%20Bengtsson.jpg?width=1024"}, {"name": "Spindle-Back Chair", "rarity": "uncommon", "id": "spindle-back-chair", "subtitle": "Everyday Chair", "details": "A row of turned wooden spindles does the work of a solid back, and looks better doing it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spindle-back_chair_MET_85B_ACF109R6.jpg?width=1024"}, {"name": "Stadium Seat", "rarity": "uncommon", "id": "stadium-seat", "subtitle": "Everyday Chair", "details": "A moulded plastic seat numbered for one fan, designed to survive sun, rain, spilled drinks, and extra time.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Olympic_stadium_munich_-_Flickr_-_markus_spiske.jpg?width=1024"}, {"name": "Strandkorb", "rarity": "uncommon", "id": "strandkorb", "subtitle": "Outdoor Chair", "details": "Germany's hooded wicker beach chair, built in 1882 to shelter one sitter from wind, sand and neighbours. A tiny cabin you wear to the beach.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20chair.jpg?width=1024"}, {"name": "Tank Chair", "rarity": "uncommon", "id": "tank-chair", "subtitle": "Design Icon", "details": "Alvar Aalto, 1936: its broad laminated-birch arm loops earned it the nickname Tank — a Paimio with shoulders.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Armchair_400_%E2%80%9CTank%E2%80%9C._Designed_by_Alvar_Aalto_1936.jpg?width=1024"}, {"name": "Teak Chair", "rarity": "uncommon", "id": "teak-chair", "subtitle": "Outdoor Chair", "details": "Grete Jalk folded teak plywood into this sculptural 1963 chair. Teak shrugs off weather so well that navies and gardens both claim it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Grete%20Jalk%20-%20GJ%20chair.jpg?width=1024"}, {"name": "The Captain's Chair", "rarity": "uncommon", "id": "the-captains-chair", "subtitle": "Throne", "details": "Centre seat on the Enterprise-D bridge, flanked by Riker and Troi. From here, 'Make it so' carried the full weight of Starfleet authority.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Enterprise-D%20bridge.jpg?width=1024"}, {"name": "The Co-Pilot's Seat", "rarity": "uncommon", "id": "the-co-pilots-seat", "subtitle": "Work Chair", "details": "The right-hand seat: identical controls, second-in-command. Every cockpit task is shared, but the left seat keeps the final word.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boeing_707-123_B_(1959)_Cockpit.jpg?width=1024"}, {"name": "The Dentist's Stool", "rarity": "uncommon", "id": "the-dentists-stool", "subtitle": "Work Chair", "details": "The dentist's own seat is a small rolling saddle that orbits the patient chair all day. The most mobile chair in the surgery.", "image": "https://www.antiquesboutique.com/upload/images/shopprod/36719/c1950-sterling-dentist-operating-stool_36719_pic1_size1.jpg"}, {"name": "The Gaming Chair", "rarity": "uncommon", "id": "the-gaming-chair", "subtitle": "Work Chair", "details": "Racing-seat styling, lumbar pillows and a recline built for long sessions: the bucket seat left the track and moved into the bedroom.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gaming_chair_1.jpg?width=1024"}, {"name": "The Hair Dryer Chair", "rarity": "uncommon", "id": "the-hair-dryer-chair", "subtitle": "Work Chair", "details": "The bonnet dryer chair defined the mid-century salon: sit, lower the hood, and wait under warm air with a magazine for company.", "image": "https://i.pinimg.com/originals/52/d4/30/52d430daaa118f0ce1bb46f1a146fe5e.jpg"}, {"name": "The Ice Throne", "rarity": "uncommon", "id": "the-ice-throne", "subtitle": "Weird Chair", "details": "A throne carved from solid ice for winter festivals. Majestic, numbing, and available for a strictly limited season before it resigns into a puddle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ice%20Thrones%20%285440976208%29.jpg?width=1024"}, {"name": "The Lab Stool", "rarity": "uncommon", "id": "the-lab-stool", "subtitle": "Work Chair", "details": "High, wipeable and backless or ring-backed, the lab stool parks a scientist at bench height and rolls out of the way just as fast.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stainless_Steel_Laboratory_Pneumatic_Chair_with_wheels.jpg?width=1024"}, {"name": "The Lily Throne", "rarity": "uncommon", "id": "the-lily-throne", "subtitle": "Throne", "details": "One of Mandalay Palace's eight thrones, kept in the chief queen's hall. Burmese kings liked options: a different throne for almost every room.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lily%20Throne%2C%20Mandalay%20Palace.jpg?width=1024"}, {"name": "The Pedicure Chair", "rarity": "uncommon", "id": "the-pedicure-chair", "subtitle": "Work Chair", "details": "A plush throne with a foot spa built in — the pedicure chair turned a foot treatment into the most comfortable seat in the salon.", "image": "https://i.pinimg.com/originals/2c/f0/4d/2cf04dba8a083a54670627a5a943d6b0.jpg"}, {"name": "The Rocking Chair", "rarity": "uncommon", "id": "the-rocking-chair", "subtitle": "Work Chair", "details": "Rockers turned a chair into gentle motion in the 1700s. Presidents, grandparents and front porches have all claimed it ever since.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rocking_Chair_(32443140351).jpg?width=1024"}, {"name": "The Stocks", "rarity": "uncommon", "id": "the-stocks", "subtitle": "Weird Chair", "details": "Lock your ankles in, sit still, and take the village's feedback in person. Reviews were delivered verbally, and sometimes as eggs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stocks-at-Waterloo-Village.JPG?width=1024"}, {"name": "The Surgeon's Stool", "rarity": "uncommon", "id": "the-surgeons-stool", "subtitle": "Work Chair", "details": "Surgeons sit for the longest, stillest work there is. Their stools adjust silently, roll on demand, and never upstage the operating table.", "image": "https://favnica.org/photos/gallery/or-stools.jpg"}, {"name": "The Tractor Seat", "rarity": "uncommon", "id": "the-tractor-seat", "subtitle": "Work Chair", "details": "Pressed steel, drainage holes and a spring underneath: the tractor seat was so good at its job that bars and workshops adopted it wholesale.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tractor_seat_Blackstone_&_Coy_Ltd.jpg?width=1024"}, {"name": "The Train Driver's Seat", "rarity": "uncommon", "id": "the-train-drivers-seat", "subtitle": "Work Chair", "details": "One seat, a deadman's vigilance pedal below and the whole line ahead. Train cabs are built around the person in this chair.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cabine_regiolis.jpg?width=1024"}, {"name": "The Witch's Chair", "rarity": "uncommon", "id": "the-witchs-chair", "subtitle": "Weird Chair", "details": "A chair upholstered in iron spikes, built to make accused witches talk. Survivors sit in museums now, where sitting is firmly discouraged.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Torture%20chair.jpg?width=1024"}, {"name": "The Workshop Stool", "rarity": "uncommon", "id": "the-workshop-stool", "subtitle": "Work Chair", "details": "A round seat, steel legs and zero upholstery to ruin: the workshop stool survives paint, oil and decades of being sat on sideways.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Workshop_stool_in_Prato,_Italy.jpeg?width=1024"}, {"name": "Thinking Man's Chair", "rarity": "uncommon", "id": "thinking-mans-chair", "subtitle": "Design Icon", "details": "Jasper Morrison's 1988 Cappellini chair of steel tube and flat bar even has little shelves for your drink and book.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jasper%20morrison%20per%20cappellini%2C%20sedia%20thinking%20man%27s%20chair%2C%201988%20%28cappellini%29.jpg?width=1024"}, {"name": "Throne of Salamis", "rarity": "uncommon", "id": "throne-of-salamis", "subtitle": "Throne", "details": "An ancient Greek marble chair from Salamis, worn pale by two millennia — proof that a throne can simply be one very good stone seat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Thron%20Salamis.JPG?width=1024"}, {"name": "Train Seat", "rarity": "uncommon", "id": "train-seat", "subtitle": "Everyday Chair", "details": "Faces forward, backward, or a stranger across a table. The window seat remains the undisputed prize.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Moscow-2024_train_interior_-_seats.jpg?width=1024"}, {"name": "Tub Chair", "rarity": "uncommon", "id": "tub-chair", "subtitle": "Everyday Chair", "details": "A barrel of a chair: one curved back wrapping around both arms. Swallows you politely, whole.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Club_chair_2.jpg?width=800"}, {"name": "Vegetal Chair", "rarity": "uncommon", "id": "vegetal-chair", "subtitle": "Design Icon", "details": "The Bouroullec brothers grew this 2008 Vitra chair from branching plant structures, injection-moulded in polyamide.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Silla%20vegetal%2C%20Ronan%20y%20Erwan%20Bouroullec.jpg?width=1024"}, {"name": "Victorian Balloon-Back Chair", "rarity": "uncommon", "id": "victorian-balloon-back-chair", "subtitle": "Historic Chair", "details": "A rounded, balloon-shaped back on cabriole legs — the polite parlour chair of Victorian Britain.", "image": "http://www.sellingantiques.co.uk/photosnew/dealer_antiquefurnituredirect/antique-victorian-walnut-balloon-back-chair-248041.jpg"}, {"name": "Well Tempered Chair", "rarity": "uncommon", "id": "well-tempered-chair", "subtitle": "Design Icon", "details": "Ron Arad bent sheets of sprung tempered steel in 1986 and bolted them, spring and all, into an armchair.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Maxistuhl%20Well%20Tempered%20Chair%20von%20Ron%20Arad%20in%20Weil%20am%20Rhein-Altweil%2C%20L%C3%B6rracher%20Str.%204.jpg?width=1024"}, {"name": "Welsh Stick Chair", "rarity": "uncommon", "id": "welsh-stick-chair", "subtitle": "Historic Chair", "details": "Handmade in Wales from sticks set into a solid wooden seat — every one different, every one built to last.", "image": "https://www.sellingantiques.co.uk/photosnew/dealer_havardandhavard/dealer_havardandhavard_full_1665749418176-6035969902.jpg"}, {"name": "Wicker Patio Chair", "rarity": "uncommon", "id": "wicker-patio-chair", "subtitle": "Outdoor Chair", "details": "Woven strands over a light frame, airy in the heat and easy to move. The patio's answer to the armchair, minus the stuffiness.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Patio%20Corner%20%2821073551598%29.jpg?width=800"}, {"name": "Windsor Bow-Back Chair", "rarity": "uncommon", "id": "windsor-bow-back-chair", "subtitle": "Historic Chair", "details": "Its back is a single bent bow of wood pierced by spindles — the classic American tavern and kitchen chair.", "image": "https://chairish-prod.freetls.fastly.net/image/product/sized/93cab205-a81c-40e8-b90b-95b7ba914fe3/antique-philadelphia-bow-back-windsor-side-chair-circa-1790s-0559?aspect=fit&height=1600&width=1600"}, {"name": "Windsor Comb-Back Chair", "rarity": "uncommon", "id": "windsor-comb-back-chair", "subtitle": "Historic Chair", "details": "A Windsor with a tall comb-shaped top rail above its spindles — part chair, part crown.", "image": "https://www.sellingantiques.co.uk/photosnew/dealer_penderynfurniture/dealer_penderynfurniture_full_1757079776133-0267043917.jpg"}, {"name": "Windsor Fan-Back Chair", "rarity": "uncommon", "id": "windsor-fan-back-chair", "subtitle": "Historic Chair", "details": "Spindles fan upward to a shaped crest rail, like a hand opened above the sitter's shoulders.", "image": "https://gcp-la8-storage-cdn.lot-art.com/public/upl/47/WINDSOR-FAN-BACK-SIDE-CHAIR_667467dfd12d5-full-78129300_1718904801-667467e1bebfa.jpg"}, {"name": "Wingnut Chair", "rarity": "uncommon", "id": "wingnut-chair", "subtitle": "Design Icon", "details": "Jasper Morrison's early plywood chair is literally held together with wing nuts — honest joinery as decoration.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Maxistuhl%20Wingnut%20Chair%20von%20Jasper%20Morrison%2C%20in%20Weil%20am%20Rhein-Altweil%2C%20Lindenplatz.jpg?width=1024"}, {"name": "World's Largest Rocking Chair", "rarity": "uncommon", "id": "worlds-largest-rocking-chair", "subtitle": "Weird Chair", "details": "In Casey, Illinois stands a rocking chair 56 feet tall, certified the world's largest. It does not rock. Given the wind, this is for the best.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/World%27s%20Largest%20Rocking%20Chair%20Casey.jpg?width=1024"}, {"name": "Zero-Gravity Lounger", "rarity": "uncommon", "id": "zero-gravity-lounger", "subtitle": "Outdoor Chair", "details": "Reclines until your feet match your heart and the weight seems to switch off. Named for astronauts, used mainly for napping.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Opened%20folding%20reclining%20chair%20with%20moss-green%20straps.jpg?width=1024"}, {"name": "A Stack of Chairs", "rarity": "common", "id": "a-stack-of-chairs", "subtitle": "Weird Chair", "details": "Chairs, stacked. The final scene of every village-hall event ever held. Currently seating: nobody, very efficiently.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stacked%20chairs%2002.jpg?width=1024"}, {"name": "Air Chair", "rarity": "common", "id": "air-chair", "subtitle": "Design Icon", "details": "Jasper Morrison's featherweight Magis chair is gas-injection moulded, so its chunky legs are really hollow tubes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Air%20chair-edit-1-2018.jpg?width=1024"}, {"name": "Airplane Seat", "rarity": "common", "id": "airplane-seat", "subtitle": "Everyday Chair", "details": "Narrower than you remember, with a tray table, a seat pocket, and strong opinions about armrest ownership.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Seats_on_an_airplane.jpg?width=1024"}, {"name": "Bar Stool", "rarity": "common", "id": "bar-stool", "subtitle": "Everyday Chair", "details": "A chair that traded its back for a footrest and extra height. Sitting, but taller.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Barhocker_%28fcm%29.jpg?width=1024"}, {"name": "Beach Chair", "rarity": "common", "id": "beach-chair", "subtitle": "Outdoor Chair", "details": "Low to the sand, light to carry, and built to recline. Its whole job is keeping you close to the water and far from your worries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20chairs%20at%20Vec%C4%81%C4%B7i%20Beach.jpg?width=1024"}, {"name": "Beach Lounger", "rarity": "common", "id": "beach-lounger", "subtitle": "Outdoor Chair", "details": "A recliner that folds flat for the walk to the shore, with a face hole for reading paperbacks face-down in the sun.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Nusa-Dua%20Bali%20Indonesia%20Sunbeds-01.jpg?width=1024"}, {"name": "Beanbag Chair", "rarity": "common", "id": "beanbag-chair", "subtitle": "Everyday Chair", "details": "A chair that gave up on structure in the 1970s and never looked back. Getting up again is cardio.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Zanotta_Sacco_chair_with_houndstooth_upholstery.jpg?width=800"}, {"name": "Bentwood Rocking Chair", "rarity": "common", "id": "bentwood-rocking-chair", "subtitle": "Design Icon", "details": "Gebrüder Thonet, from the 1860s: steam-bent beech scrolled into rockers — the café chair that learned to sway.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/No._4_Rocking_Chair%2C_ca._1860_%28CH_18467803%29.jpg?width=1024"}, {"name": "Berlin Chair", "rarity": "common", "id": "berlin-chair", "subtitle": "Design Icon", "details": "Rietveld, 1923: eight painted wooden planks and nothing else — a sculpture that happens to hold a person.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/BERLIN_CHAIR.jpg?width=1024"}, {"name": "Bus Seat", "rarity": "common", "id": "bus-seat", "subtitle": "Everyday Chair", "details": "A high-backed seat in patterned fabric, with the window view included and the aisle view tolerated.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Passenger_Seats_of_Trans_Metro_Pasundan_Corridor_3D.jpg?width=1024"}, {"name": "Butaque", "rarity": "common", "id": "butaque", "subtitle": "Historic Chair", "details": "Mexico's X-frame lounge chair blends Spanish colonial and pre-Hispanic roots into one low, lean-back seat.", "image": "https://ambianic.com/wp-content/uploads/2024/01/Miguelito-Chair-Old-08-25-1-scaled.jpg"}, {"name": "Cafeteria Chair", "rarity": "common", "id": "cafeteria-chair", "subtitle": "Everyday Chair", "details": "Wipe-clean, tray-compatible, and arranged for maximum lunchtime noise in the minimum possible space.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lymanhurst_School_Cafeteria_-_DPLA_-_22226d1395129f6a828c172dd418bfce.jpg?width=1024"}, {"name": "Camp Stool", "rarity": "common", "id": "camp-stool", "subtitle": "Outdoor Chair", "details": "Three legs and a triangle of canvas: the lightest possible agreement between a person and the ground. Campers have carried them for centuries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Camping%20stool.jpg?width=1024"}, {"name": "Campeachy Chair", "rarity": "common", "id": "campeachy-chair", "subtitle": "Historic Chair", "details": "A low leather sling chair from Campeche, Mexico, beloved in Louisiana parlours — Jefferson owned several.", "image": "https://www.themagazineantiques.com/wp-content/uploads/2009/05/1.jpeg"}, {"name": "Caquetoire", "rarity": "common", "id": "caquetoire", "subtitle": "Historic Chair", "details": "A French Renaissance armchair with a trapezoid seat — named for the chatter it hosted over long conversations.", "image": "https://collectionapi.metmuseum.org/api/collection/v1/iiif/460643/917945/main-image"}, {"name": "Card Table Chair", "rarity": "common", "id": "card-table-chair", "subtitle": "Everyday Chair", "details": "Padded vinyl on folding legs, built for bridge night. Folds flat, keeps the scores secret.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Folding_Chair_from_Visitor%27s_Locker_Room_at_Busch_Stadium_-_DPLA_-_1b743261951f382bf63b7b01fba3e259_%28page_1%29.jpg?width=1024"}, {"name": "Cardboard Chair", "rarity": "common", "id": "cardboard-chair", "subtitle": "Weird Chair", "details": "Folded flat-pack's ancestor: corrugated card, slot-together, genuinely holds a person. Its natural predator is rain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cardboard%20Furniture.jpg?width=1024"}, {"name": "Chair Made of Skis", "rarity": "common", "id": "chair-made-of-skis", "subtitle": "Weird Chair", "details": "Retired skis bolted into an Adirondack frame. The only chair in the set that has already been down the mountain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Adirondack%20Ski%20Chair%20Butternut%20Ski%20Area%20and%20Tubing%20Center%20Great%20Barrington.jpg?width=1024"}, {"name": "Charpai", "rarity": "common", "id": "charpai", "subtitle": "Historic Chair", "details": "India's woven rope bed-chair: four legs and a webbed frame, equally at home for sitting, napping and guests.", "image": "https://i.etsystatic.com/58483523/r/il/63b705/7855428550/il_1080xN.7855428550_47i3.jpg"}, {"name": "Child Car Seat", "rarity": "common", "id": "child-car-seat", "subtitle": "Everyday Chair", "details": "Five points of harness, a forest of straps, and crumbs in places no vacuum has ever reached.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Child_car_seat.JPG?width=800"}, {"name": "Children's Chair", "rarity": "common", "id": "childrens-chair", "subtitle": "Everyday Chair", "details": "A proper chair, shrunk. Everything is the same except the size and how seriously it is taken.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/CreativeTools.se_-_PackshotCreator_-_3D_printed_IKEA_Mammut_chair_%284711038679%29.jpg?width=1024"}, {"name": "Children's Wooden Chair", "rarity": "common", "id": "childrens-wooden-chair", "subtitle": "Everyday Chair", "details": "A small wooden chair at a small wooden table, headquarters for tea parties, drawings, and important meetings.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%D0%95%D0%BB%D1%8C%D1%81%D0%BA._%D0%94%D0%B7%D1%96%D1%86%D1%8F%D1%87%D1%8B_%D1%81%D0%B0%D0%B4_%E2%84%962_%2801%29.jpg?width=1024"}, {"name": "Chinese Drum Stool", "rarity": "common", "id": "chinese-drum-stool", "subtitle": "Historic Chair", "details": "A barrel-shaped stool, often porcelain, that has doubled as seat, table and garden ornament for centuries.", "image": "https://d2rubhnb90tqe7.cloudfront."}, {"name": "Chinese Rose Chair", "rarity": "common", "id": "chinese-rose-chair", "subtitle": "Historic Chair", "details": "A low-backed Ming-dynasty chair in dense rosewood — its small back was never meant for slouching.", "image": "https://cdn.incollect.com/sites/default/files/zoom/Chinese-Qing-style-Rose-Chair-759148-3873997.jpg"}, {"name": "Classroom Chair", "rarity": "common", "id": "classroom-chair", "subtitle": "Everyday Chair", "details": "A small, tough chair built to survive a school year of swinging back on two legs despite constant warnings.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/A_chair_is_placed_by_the_window_in_an_empty_classroom_at_a_school_near_Bagram_Airfield%2C_Parwan_province%2C_Afghanistan%2C_April_16%2C_2014_140416-A-IY570-142.jpg?width=1024"}, {"name": "Classroom Stool", "rarity": "common", "id": "classroom-stool", "subtitle": "Everyday Chair", "details": "A backless stool for science labs and art rooms, where sitting still was never really the point.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Science_Lab_at_Regent%27s_International_School_Bangkok.jpg?width=1024"}, {"name": "Counter Stool", "rarity": "common", "id": "counter-stool", "subtitle": "Everyday Chair", "details": "The bar stool's domestic cousin, sized for kitchen islands, breakfasts and supervised homework.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Six-Stool_Lunch_Counter.jpg?width=1024"}, {"name": "Deck Chair", "rarity": "common", "id": "deck-chair", "subtitle": "Outdoor Chair", "details": "A folding frame and a sling of striped canvas, born on ocean liners. Famously simple, and famously tricky to unfold the first time.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Deckchair%20600.jpg?width=1024"}, {"name": "Desk Chair", "rarity": "common", "id": "desk-chair", "subtitle": "Everyday Chair", "details": "Five wheels, one mysterious lever, and a gas lift that sinks slowly through every long session.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Executive_chair.jpg?width=1024"}, {"name": "Eames Wire Chair", "rarity": "common", "id": "eames-wire-chair", "subtitle": "Design Icon", "details": "1951: the Eames shell reborn in welded wire with a two-piece 'bikini' pad, on the famous Eiffel-tower base.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Basket%26Wire-chair.jpg?width=1024"}, {"name": "Exam Stool", "rarity": "common", "id": "exam-stool", "subtitle": "Everyday Chair", "details": "A plain wooden stool from a doctor's office: no wheels, no padding, no nonsense. Examinations were endured, not enjoyed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wooden_stool%2C_originally_from_a_doctor%27s_office_in_Asperg%2C_Germany%2C_dating_from_the_1930s._Captured_in_Tegernsee%2C_Bavaria.jpeg?width=1024"}, {"name": "Exercise Ball Chair", "rarity": "common", "id": "exercise-ball-chair", "subtitle": "Weird Chair", "details": "An office chair that resigned and became a ball. Posture: improved. Dignity: negotiable. Rolling away mid-meeting: a feature.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Red%20ball%20in%20the%20office%20%288360332987%29.jpg?width=700"}, {"name": "Farmhouse Chair", "rarity": "common", "id": "farmhouse-chair", "subtitle": "Everyday Chair", "details": "Slatted back, a woven seat and two centuries of farmhouse kitchens behind it. Built for long tables and longer lunches.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/French_Colonial_Slat-Back_Prie-Dieu_Chair_-_DPLA_-_ac9bbcd62e8306d33d49863b309923be_%28page_2%29.jpg?width=1024"}, {"name": "Ferry Seat", "rarity": "common", "id": "ferry-seat", "subtitle": "Everyday Chair", "details": "A bolted-down seat that faces the water, built for crossings, sea air, and watching the harbour arrive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/MV_Spokane_empty_passenger_cabin_during_COVID_crisis.jpg?width=1024"}, {"name": "Folding Camp Chair", "rarity": "common", "id": "folding-camp-chair", "subtitle": "Outdoor Chair", "details": "Fabric, aluminium tubes and a cup holder in the armrest. It folds into a bag and has heard every campfire story ever told.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Helinox%20Ground%20Chair%201.jpg?width=1024"}, {"name": "Garden Bench", "rarity": "common", "id": "garden-bench", "subtitle": "Outdoor Chair", "details": "A plain bench placed where the garden looks best. It is less furniture than an instruction: stop here, and look at the flowers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bredevoort%20%28NL%29%2C%20Parkbank%20--%202016%20--%201398.jpg?width=1024"}, {"name": "Garden Egg Chair", "rarity": "common", "id": "garden-egg-chair", "subtitle": "Design Icon", "details": "Peter Ghyczy's 1968 egg opens for sitting and closes into a smooth pod — a chair with a lid, made for the garden.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gardeneggchair.jpg?width=1024"}, {"name": "Glastonbury Chair", "rarity": "common", "id": "glastonbury-chair", "subtitle": "Historic Chair", "details": "A folding X-frame chair with carved arms, named for chairs linked to Glastonbury Abbey in England.", "image": "https://cdn20.pamono.com/p/s/2/1/2111538_o51476i71a/english-glastonbury-chair-in-oak-1880s.jpg"}, {"name": "Hall Chair", "rarity": "common", "id": "hall-chair", "subtitle": "Historic Chair", "details": "A hard, narrow seat made for hallways — for waiting visitors and putting on boots, never for lingering.", "image": "https://cdn.incollect.com/sites/default/files/medium/A-Rare-Pair-of-Regency-Mahogany-Hourglass-Form-Hall-Chairs-873104-4696667.jpeg"}, {"name": "Hammock Chair", "rarity": "common", "id": "hammock-chair", "subtitle": "Outdoor Chair", "details": "Half hammock, half chair, hung from a single point. It sways as you sit, which makes standing back up entirely optional.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BCnchen%20%E2%80%94%20Rablstra%C3%9Fe%202%20%28H%C3%A4ngesessel%29.jpg?width=800"}, {"name": "High Chair", "rarity": "common", "id": "high-chair", "subtitle": "Everyday Chair", "details": "A throne with a tray and straps, because the small king throws his food on the floor.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/High_chair.jpg?width=1024"}, {"name": "Hitchcock Chair", "rarity": "common", "id": "hitchcock-chair", "subtitle": "Historic Chair", "details": "Lambert Hitchcock's Connecticut factory stencilled fruit and flowers in gold onto black chairs by the thousand.", "image": "https://onton.com/images/webp/1024/d788f346-cf07-5ec2-81fb-d1b64ad72b94"}, {"name": "Hospital Waiting Chair", "rarity": "common", "id": "hospital-waiting-chair", "subtitle": "Everyday Chair", "details": "A wipe-clean seat in a calm colour, doing quiet, patient work in corridors and clinics around the clock.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/HK_%E5%B1%AF%E9%96%80%E9%86%AB%E9%99%A2_Tuen_Mun_Hospital_ground_floor_Pharmacy_service_counter_window_n_waiting_room_plastic_seats_July_2016_DSC.jpg?width=1024"}, {"name": "Inflatable Chair", "rarity": "common", "id": "inflatable-chair", "subtitle": "Everyday Chair", "details": "Half chair, half balloon. Sit gently, bounce slightly, and keep it away from sharp corners and sceptics.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Inflatable_animal_air_chair-3-xavier_cottage-yercaud-salem-India.jpg?width=1024"}, {"name": "Kids' Plastic Chair", "rarity": "common", "id": "kids-plastic-chair", "subtitle": "Everyday Chair", "details": "A miniature chair in a primary colour, light enough for its owner to carry it proudly across the room alone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/HK_CWB_Park_Lane_basement_shop_IKEA_chairs_plastic_n_children_Dec-2015_DSC.JPG?width=1024"}, {"name": "Kitchen Bench", "rarity": "common", "id": "kitchen-bench", "subtitle": "Everyday Chair", "details": "One long seat for three children, two adults, or every coat in the house by Friday.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bishops_House_Dining_Room_2014.JPG?width=1024"}, {"name": "Kuba Stool", "rarity": "common", "id": "kuba-stool", "subtitle": "Historic Chair", "details": "Carved wooden stools of the Kuba people of the Congo, patterned with interlace designs.", "image": "https://images.metmuseum.org/CRDImages/ao/web-large/1979.206.51_a.jpg"}, {"name": "Ladderback Chair", "rarity": "common", "id": "ladderback-chair", "subtitle": "Historic Chair", "details": "Horizontal slats climb the back like a ladder: cheap, sturdy, and at home in farm kitchens for centuries.", "image": "https://www.sellingantiques.co.uk/photosnew/dealer_rogerking/dealer_rogerking_superhighres_1779545942324-4572892158.jpg"}, {"name": "Laleggera Chair", "rarity": "common", "id": "laleggera-chair", "subtitle": "Design Icon", "details": "Riccardo Blumer's 1996 Alias chair weighs barely two kilos: a wooden skin glued over a light core, aircraft-style.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Laleggera.jpg?width=1024"}, {"name": "Lawn Chair", "rarity": "common", "id": "lawn-chair", "subtitle": "Outdoor Chair", "details": "The classic folding aluminium frame strung with woven webbing. It has attended more barbecues, parades and fireworks than anyone can count.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Folding%20chair%20and%20surfboard%20at%20a%20beach%20house%2C%20Auckland%20-%200999.jpg?width=800"}, {"name": "Log Bench", "rarity": "common", "id": "log-bench", "subtitle": "Outdoor Chair", "details": "A log, halved or notched, doing the oldest job in furniture. No assembly, no instructions, no moving parts — just sit.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Log%20furniture%20bench%202021.jpg?width=1024"}, {"name": "Lunchroom Bench Table", "rarity": "common", "id": "lunchroom-bench-table", "subtitle": "Everyday Chair", "details": "Table and benches in one folding unit: an entire lunchroom that packs away so the hall can become a gym again.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Calhan_Colorado_High_School_Cafeteria_by_David_Shankbone.jpg?width=1024"}, {"name": "Mesh Office Chair", "rarity": "common", "id": "mesh-office-chair", "subtitle": "Work Chair", "details": "A breathable mesh back on a five-star base: by the 2000s this had quietly become the default seat of office work everywhere.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Think_Chair.jpg?width=1024"}, {"name": "Metal Folding Chair", "rarity": "common", "id": "metal-folding-chair", "subtitle": "Everyday Chair", "details": "Clangs open, pinches fingers, seats the overflow crowd. Lives folded in the garage between events.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Egon_Eiermann_Klappstuhl_SE_18_v.jpg?width=1024"}, {"name": "Metal Patio Chair", "rarity": "common", "id": "metal-patio-chair", "subtitle": "Outdoor Chair", "details": "A springy steel frame that gently bounces as you sit. Many designs date to the 1940s and simply refuse to wear out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Metal%20Garden%20Chair.jpg?width=800"}, {"name": "Monks Bench", "rarity": "common", "id": "monks-bench", "subtitle": "Historic Chair", "details": "Its back flips over to become a tabletop: a bench by day, a table by night, and a space-saver for centuries.", "image": "https://content.easyliveauction.com/auctions/images_lots/E5C5C6C5753EDB394AD2487BA0F7B0E5_ear01/1101508397_PREVIEW.JPG"}, {"name": "Monobloc Chair", "rarity": "common", "id": "monobloc-chair", "subtitle": "Everyday Chair", "details": "One piece of moulded plastic, stacked on patios worldwide. Possibly the most-produced chair on Earth.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/White_Monobloc_chair.jpg?width=1024"}, {"name": "Musical Chairs", "rarity": "common", "id": "musical-chairs", "subtitle": "Weird Chair", "details": "One chair fewer than players. The music stops, friendships pause, and somebody sits on the floor. The world's most honest seating plan.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Musical%20chairs%20Lawn%20Jam%20Our%20Community%20Place%20Harrisonburg%20VA%20June%202008.jpg?width=1024"}, {"name": "Office Visitor Chair", "rarity": "common", "id": "office-visitor-chair", "subtitle": "Everyday Chair", "details": "The chair on the other side of the desk. Slightly lower, slightly plainer, and it knows it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Breuer-FREISCHWINGER.JPG?width=1024"}, {"name": "Park Bench", "rarity": "common", "id": "park-bench", "subtitle": "Outdoor Chair", "details": "Slats of wood or steel on cast-iron legs, bolted to the world. Feeds pigeons, holds lunches, and watches the whole town go by.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bank%20in%20Engelse%20tuin.%20Locatie%2C%20Tuinen%20Mien%20Ruys.jpg?width=1024"}, {"name": "Patio Bar Chair", "rarity": "common", "id": "patio-bar-chair", "subtitle": "Outdoor Chair", "details": "A tall outdoor stool for counters, tiki bars and balcony rails. Same view as standing, with the considerable upgrade of sitting.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Max%20Gottschalk%20-%20Bar%20stool%206.jpg?width=1024"}, {"name": "Patio Dining Chair", "rarity": "common", "id": "patio-dining-chair", "subtitle": "Outdoor Chair", "details": "The chair at the outdoor table, built to survive both weather and long dinners. Alfresco meals are measured in hours, not courses.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Prinknash%20Abbey%20Walled%20Garden%20outdoor%20table%20and%20chairs%20Upton%20St%20Leonards%20Gloucestershire%20England.jpg?width=1024"}, {"name": "Picnic Bench", "rarity": "common", "id": "picnic-bench", "subtitle": "Outdoor Chair", "details": "The bench half of the picnic table, permanently attached to its partner. Eating indoors at one feels technically possible, spiritually wrong.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Picnic%20table%20Hoveniersdreef%20Heverlee.jpg?width=800"}, {"name": "Plastic Stacking Chair", "rarity": "common", "id": "plastic-stacking-chair", "subtitle": "Everyday Chair", "details": "Stacks ten high, shrugs off rain, and fills any hall that needs fifty seats by noon.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stacked_chairs_02.jpg?width=1024"}, {"name": "Plia Chair", "rarity": "common", "id": "plia-chair", "subtitle": "Design Icon", "details": "Giancarlo Piretti's clear Lucite folder of the late 1960s folds flat with a three-disc hinge — the folding chair, clarified.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ngv%20design%2C%20giancarlo%20piretti%2C%20plia%20folding%20chair%2C%201969%2002.JPG?width=1024"}, {"name": "Ply Chair", "rarity": "common", "id": "ply-chair", "subtitle": "Design Icon", "details": "Jasper Morrison cut this chair from just a few sheets of plywood, bent and screwed — his 1980s manifesto in furniture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Maxistuhl%20Ply%20Chair%20von%20Jasper%20Morrison%20in%20Weil%20am%20Rhein-%20Haltingen%2C%20Winzerweg%208.jpg?width=700"}, {"name": "Pony Chair", "rarity": "common", "id": "pony-chair", "subtitle": "Design Icon", "details": "Eero Aarnio's 1973 Pony is a toy you sit on: a friendly foam steed, sized for grown-ups as much as children.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eero%20Aarnio%2C%20the%20Pony%20Chair.jpg?width=700"}, {"name": "Porch Bench", "rarity": "common", "id": "porch-bench", "subtitle": "Outdoor Chair", "details": "A simple bench by the front door — for lacing boots, shelling peas, and watching the street decide what the day will be.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Flickr%20-%20brewbooks%20-%20Front%20Porch%20of%20Ravensworth.jpg?width=1024"}, {"name": "Pouf", "rarity": "common", "id": "pouf", "subtitle": "Everyday Chair", "details": "A cushion that insists it is furniture: seat, footrest or side table, depending on who asks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Puff_Redondo_Baixo_2.jpg?width=1024"}, {"name": "Resin Folding Chair", "rarity": "common", "id": "resin-folding-chair", "subtitle": "Everyday Chair", "details": "The white folding chair of weddings everywhere: smart in photos, tough enough for the dancing.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Outdoor_Wedding_Chairs_2816px.jpg?width=1024"}, {"name": "Safari Chair", "rarity": "common", "id": "safari-chair", "subtitle": "Design Icon", "details": "Kaare Klint, 1933: a knock-down campaign chair in leather and ash that assembles with no tools at all.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Safari_chair_Kaare_Klint.jpg?width=1024"}, {"name": "School Desk-Chair Combo", "rarity": "common", "id": "school-desk-chair-combo", "subtitle": "Everyday Chair", "details": "Seat and desk fused into one unit, with a wire rack underneath sized for exactly one textbook and some crumbs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Students_in_a_classroom.jpg?width=1024"}, {"name": "Settle Bench", "rarity": "common", "id": "settle-bench", "subtitle": "Historic Chair", "details": "A high-backed wooden bench, sometimes with a chest under the seat — the draught-proof heart of old cottages.", "image": "https://assets-vinterior-0.vinterior.co/uploads/listing_image/image/15727255/large_antique-fine-quality-georgian-oak-settle-bench-seat-c-1790-elegant-18th-century-furniture-sku88411953_0.jpg"}, {"name": "Sgabello", "rarity": "common", "id": "sgabello", "subtitle": "Historic Chair", "details": "A Renaissance Italian side chair on trestle supports, its back carved with coats of arms and scrolls.", "image": "https://images.metmuseum.org/CRDImages/rl/web-large/SLP1989-1.jpg"}, {"name": "Shower Chair", "rarity": "common", "id": "shower-chair", "subtitle": "Everyday Chair", "details": "A waterproof seat that makes showers safer and steadier. Unspectacular, essential, quietly brilliant.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Transfer_bench.jpg?width=1024"}, {"name": "Slat-Back Chair", "rarity": "common", "id": "slat-back-chair", "subtitle": "Historic Chair", "details": "Wide shaped slats, often bent to the sitter's back, define this American country staple with Shaker roots.", "image": "https://assets-vinterior-3.vinterior.co/uploads/listing_image/image/21353288/large_antique-arts-crafts-sussex-chair-william-morris-style-rush-seat-103056-sku45667336_0.jpg"}, {"name": "Smoking Chair", "rarity": "common", "id": "smoking-chair", "subtitle": "Historic Chair", "details": "Victorian gentlemen sat astride it backwards, elbows on its padded top rail, cigar in hand.", "image": "https://s1.img.bidsquare.com/item/xl/1127/11276046.jpeg"}, {"name": "Spanish Chair", "rarity": "common", "id": "spanish-chair", "subtitle": "Design Icon", "details": "Børge Mogensen, 1958: oak and saddle leather with buckled straps you tighten as the leather ages.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%B8rge_Mogensen_-_Spannish_chair.jpg?width=1024"}, {"name": "Step Stool Chair", "rarity": "common", "id": "step-stool-chair", "subtitle": "Everyday Chair", "details": "A chair that is secretly a ladder. Flip the top, climb up, reach the tin hidden from you.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ottakringer_leiterstuhl_%28katarina_noever_1978%29.jpg?width=1024"}, {"name": "Stone Garden Bench", "rarity": "common", "id": "stone-garden-bench", "subtitle": "Outdoor Chair", "details": "Carved once, seated forever. Stone benches in old gardens have held centuries of sitters and will hold centuries more.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/West%20Smithfield%20Gardens%2C%20sculptured%20stone%20bench%20%282%29.jpg?width=1024"}, {"name": "Student Stacking Chair", "rarity": "common", "id": "student-stacking-chair", "subtitle": "Everyday Chair", "details": "Designed to stack ten high at the end of the day, which is the closest most chairs get to a team sport.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Plastic_stacking_chairs_designed_by_Robin_Day.jpg?width=1024"}, {"name": "Stump Chair", "rarity": "common", "id": "stump-chair", "subtitle": "Weird Chair", "details": "A tree, retired and re-employed. One cut for the seat, one for the backrest, upholstery by moss, termites pending.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stump%20chair%20-%20panoramio.jpg?width=700"}, {"name": "Subway Bench", "rarity": "common", "id": "subway-bench", "subtitle": "Everyday Chair", "details": "A station bench shared with commuters, pigeons, and one bag that is definitely taking up a seat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Munich_Subway_Station_Georg-Brauchle-Ring%2C_April_2017.jpg?width=1024"}, {"name": "Sun Lounger", "rarity": "common", "id": "sun-lounger", "subtitle": "Outdoor Chair", "details": "A long, low recliner built for one purpose: following the sun across the sky at the slowest possible speed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9B%D0%B5%D0%B6%D0%B0%D0%BA.JPG?width=1024"}, {"name": "Sussex Chair", "rarity": "common", "id": "sussex-chair", "subtitle": "Historic Chair", "details": "A light rush-seated country chair revived by William Morris's circle and copied across Victorian England.", "image": "https://assets-vinterior-2.vinterior.co/uploads/listing_image/image/21353287/large_antique-arts-crafts-sussex-chair-william-morris-style-rush-seat-103056-sku45667336_0.jpg"}, {"name": "The Bucket Seat", "rarity": "common", "id": "the-bucket-seat", "subtitle": "Weird Chair", "details": "A car seat shaped to hold you in the corners: deep bolsters, a low perch, and a name borrowed from a bucket it does not resemble.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bucket%20seat%20with%20Schroth%20six-point%20harness%20in%20a%202010%20Porsche%20997%20GT3%20RS%203.8.jpg?width=1024"}, {"name": "The Commode Chair", "rarity": "common", "id": "the-commode-chair", "subtitle": "Weird Chair", "details": "A chair with a hole in the seat and a bucket underneath: plumbing's understudy. Before bathrooms, this was the en-suite.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toilet%20chair%20%2801%29.jpg?width=1024"}, {"name": "The Intern's Chair", "rarity": "common", "id": "the-interns-chair", "subtitle": "Work Chair", "details": "Every office has one: wobbles slightly, squeaks on the left castor, and goes to whoever arrived last. A rite of passage with armrests.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Desk_chair.jpg?width=1024"}, {"name": "The Mechanic's Creeper Stool", "rarity": "common", "id": "the-mechanics-creeper-stool", "subtitle": "Work Chair", "details": "A low rolling seat that keeps a mechanic at wheel height all day, tools in its tray and castors where its feet should be.", "image": "https://www.therange.co.uk/media/8/3/1737081251_11_1109.jpg"}, {"name": "The Pub Stool", "rarity": "common", "id": "the-pub-stool", "subtitle": "Work Chair", "details": "Short, round and padded in vinyl: the pub stool tucks under the smallest table and has absorbed a century of celebrations and sorrows.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Barhocker_(fcm).jpg?width=1024"}, {"name": "The Salon Waiting Chair", "rarity": "common", "id": "the-salon-waiting-chair", "subtitle": "Work Chair", "details": "It holds the next appointment, a stack of magazines and a quiet nervousness about the haircut to come. Time measured in pages.", "image": "https://cdn.healthdish.com/2023/10/13/23-Wikimedia-Commons-1.jpeg"}, {"name": "The Shampoo Chair", "rarity": "common", "id": "the-shampoo-chair", "subtitle": "Work Chair", "details": "It leans you back into the basin and takes your full weight at the neck. For many clients, the shampoo chair is the best seat in the salon.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/O'Naturals-4thAnniversary-96.jpg?width=1024"}, {"name": "The Swivel Chair", "rarity": "common", "id": "the-swivel-chair", "subtitle": "Work Chair", "details": "Thomas Jefferson is credited with an early swivel chair in the 1770s. Every office argument since has been chaired from one of its descendants.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Desk_Chair_Used_By_Paul_J._Morrin_-_DPLA_-_7cc3790a58d9aab6a89e88249ebc7023_(page_1).jpg?width=1024"}, {"name": "The Tire Chair", "rarity": "common", "id": "the-tire-chair", "subtitle": "Weird Chair", "details": "Old tires, cut and woven into a sturdy seat in a Senegal workshop. The tread's second career involves considerably less travel.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chaise%20en%20pneus%20recycl%C3%A9s%20%C3%A0%20Toubab%20Dialaw%20%E2%B8%BB.jpg?width=1024"}, {"name": "Tire Swing Seat", "rarity": "common", "id": "tire-swing-seat", "subtitle": "Outdoor Chair", "details": "An old tyre on a rope, retired from the road to a far better job. Seating, swing and roundabout in one recycled circle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Car%20tire%20used%20as%20swing%20in%20Rancho%2C%20Oranjestad%20Aruba.jpg?width=800"}, {"name": "Toilet Seat", "rarity": "common", "id": "toilet-seat", "subtitle": "Weird Chair", "details": "The throne's only moving part, shown here in commemorative ocean-print. Left up or down in defiance of household law since records began.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Decorative%20toilet%20seat.jpg?width=1024"}, {"name": "Tree Stump Seat", "rarity": "common", "id": "tree-stump-seat", "subtitle": "Outdoor Chair", "details": "A tree stump, carved or flat-topped, doing the oldest job in furniture: seat, side table and footrest in rotation, no assembly required.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Seat%20carved%20from%20a%20tree%20stump%20-%20geograph.org.uk%20-%20876913.jpg?width=1024"}, {"name": "Tree Swing", "rarity": "common", "id": "tree-swing", "subtitle": "Outdoor Chair", "details": "A plank, two ropes and one strong branch — the simplest seat ever hung. Flight included, at least for a few seconds at a time.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sacalum%2C%20Yucatan%2C%20Mexico%20-%20Tree%20Swing.jpg?width=1024"}, {"name": "Tripp Trapp", "rarity": "common", "id": "tripp-trapp", "subtitle": "Design Icon", "details": "Peter Opsvik's 1972 Stokke high chair adjusts as a child grows, so the same seat works from toddler to teenager.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/STOKKE%20TRIPP%20TRAPP%20%283891978042%29.jpg?width=1024"}, {"name": "Upholstered Dining Chair", "rarity": "common", "id": "upholstered-dining-chair", "subtitle": "Everyday Chair", "details": "Padding where it counts, fabric where the gravy lands. Brought out when meals require cutlery.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dining_chair_1939.jpg?width=800"}, {"name": "Utrecht Chair", "rarity": "common", "id": "utrecht-chair", "subtitle": "Design Icon", "details": "Rietveld, 1935: thick upholstered planes joined at bold angles, later famous in Cassina's colourful felt editions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/UN_Delegates%27_Lounge_New_York_%289916986025%29_%28cropped%29_-_Rietveld%27s_Utrecht_Lounge_Chair.jpg?width=1024"}, {"name": "Waiting Room Chair", "rarity": "common", "id": "waiting-room-chair", "subtitle": "Everyday Chair", "details": "Chosen from a row of identical seats, next to the magazines, under a clock that everyone keeps checking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Social_Distanced_Waiting_Room%2C_LSU_Healthcare%2C_New_Orleans%2C_Sept_2022_02.jpg?width=1024"}, {"name": "Windsor Low-Back Chair", "rarity": "common", "id": "windsor-low-back-chair", "subtitle": "Historic Chair", "details": "The earliest Windsor form: a low curved arm rail on short spindles, at home by any fireside.", "image": "https://onton.com/images/webp/1024/3a407fa3-8a6c-5915-8797-65e7188e6ffd"}, {"name": "Windsor Rod-Back Chair", "rarity": "common", "id": "windsor-rod-back-chair", "subtitle": "Historic Chair", "details": "A later, lighter Windsor whose short spindles — rods — meet a simple rail; a New England favourite around 1800.", "image": "https://cdn.incollect.com/sites/default/files/zoom/Rod-Back-Windsor-Side-Chair-634360-3039171.jpeg"}, {"name": "Windsor Sack-Back Chair", "rarity": "common", "id": "windsor-sack-back-chair", "subtitle": "Historic Chair", "details": "A sack hood could be drawn over its bowed back to block draughts — the name stuck long after the hoods vanished.", "image": "https://a.1stdibscdn.com/late-18th-c-sack-back-new-england-windsor-chair-for-sale-picture-2/f_57512/f_288879421653965573583/f_28887942_1653965575097_bg_processed.jpg"}, {"name": "Wooden Kitchen Chair", "rarity": "common", "id": "wooden-kitchen-chair", "subtitle": "Everyday Chair", "details": "Four legs, a hard seat and decades of breakfasts. The wobble is a family heirloom feature.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kitchen_chair_made_by_L%C3%BCbke._Germany.jpeg?width=1024"}]});
